-- 3. Liste des articles (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Liste des articles',
N'SELECT F_ARTICLE.cbMarq AS [Code interne], CASE F_ARTICLE.AR_Type WHEN 0 THEN ''Standard'' WHEN 1 THEN ''Gamme'' WHEN 2 THEN ''Ressource Prestation'' WHEN 3 THEN ''Ressource Location'' END AS [Type Article], F_ARTICLE.AR_Ref AS [Code Article], F_ARTICLE.AR_Design AS [Désignation Article], F_ARTICLE.FA_CodeFamille AS [Code Famille], F_FAMILLE.FA_Intitule AS [Intitulé famille], F_FAMILLE_1.FA_Intitule AS [Intitulé Famille Centralisatrice], P_GAMME.G_Intitule AS [Libellé Gamme 1], P_GAMME_1.G_Intitule AS [Libellé Gamme 2], F_CATALOGUE.CL_Intitule AS [Catalogue 1], F_CATALOGUE_1.CL_Intitule AS [Catalogue 2], F_CATALOGUE_2.CL_Intitule AS [Catalogue 3], F_CATALOGUE_3.CL_Intitule AS [Catalogue 4], ISNULL(P_CONDITIONNEMENT.P_Conditionnement, ''Aucun'') AS Conditionnement, P_UNITE.U_Intitule AS [Unité Vente], F_ARTICLE.AR_PrixAch AS [Prix d''achat], F_ARTICLE.AR_PUNet AS [Dernier prix d''achat], F_ARTICLE.AR_Coef AS Coefficient, F_ARTICLE.AR_PrixVen AS [Prix de vente], CASE F_ARTICLE.AR_SuiviStock WHEN 0 THEN ''Aucun'' WHEN 1 THEN ''Sérialisé'' WHEN 2 THEN ''CMUP'' WHEN 3 THEN ''FIFO'' WHEN 4 THEN ''LIFO'' WHEN 5 THEN ''Par lot'' END AS [Suivi Stock], F_ARTICLE.AR_PoidsNet AS [Poids Net], F_ARTICLE.AR_PoidsBrut AS [Poids Brut], CASE F_ARTICLE.AR_Sommeil WHEN 0 THEN ''Actif'' WHEN 1 THEN ''En sommeil'' END AS [Actif / Sommeil], F_ARTICLE.AR_CodeBarre AS [Code Barres], F_ARTICLE.cbCreation [Date création], F_ARTICLE.cbModification [Date modification] FROM P_CONDITIONNEMENT RIGHT OUTER JOIN P_UNITE RIGHT OUTER JOIN F_CATALOGUE RIGHT OUTER JOIN F_ARTICLE LEFT OUTER JOIN F_FAMILLE AS F_FAMILLE_1 RIGHT OUTER JOIN F_FAMILLE ON F_FAMILLE_1.FA_CodeFamille = F_FAMILLE.FA_Central ON F_ARTICLE.FA_CodeFamille = F_FAMILLE.FA_CodeFamille LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_3 ON F_ARTICLE.CL_No4 = F_CATALOGUE_3.CL_No LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_2 ON F_ARTICLE.CL_No3 = F_CATALOGUE_2.CL_No LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_1 ON F_ARTICLE.CL_No2 = F_CATALOGUE_1.CL_No ON F_CATALOGUE.CL_No = F_ARTICLE.CL_No1 ON P_UNITE.cbIndice = F_ARTICLE.AR_UniteVen ON P_CONDITIONNEMENT.cbIndice = F_ARTICLE.AR_Condition LEFT OUTER JOIN P_GAMME AS P_GAMME_1 ON F_ARTICLE.AR_Gamme2 = P_GAMME_1.cbIndice LEFT OUTER JOIN P_GAMME ON F_ARTICLE.AR_Gamme1 = P_GAMME.cbIndice',
N'Articles', N'Code Article', N'DB', 'incremental', N'Date modification', 'high', 3, 1);

-- 4. Liste des clients (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Liste des clients',
N'SELECT F_COMPTET.CT_Qualite AS Qualité, F_COMPTET.CT_Num AS [Code client], F_COMPTET.CT_Intitule AS [Intitulé], F_COMPTET.CT_Classement AS [Classement], case when F_COMPTET.CO_No =0 then null else F_COMPTET.CO_No end AS [Code représentant], CO_Nom+'' ''+CO_Prenom AS [Représentant], F_COMPTET.CT_NumPayeur AS [Code payeur], F_COMPTET_1.CT_Intitule AS [Tiers payeur], ISNULL(P_DEVISE.D_Intitule, ''Aucune'') AS [Devise], P_CATTARIF.CT_Intitule AS [Catégorie tarifaire], ISNULL(F_DEPOT.DE_Intitule, ''Dépôt principal'') AS [Dépôt de rattachement], CASE F_COMPTET.CT_Sommeil WHEN 0 THEN ''Actif'' WHEN 1 THEN ''En sommeil'' END AS [En sommeil], F_COMPTET.CG_NumPrinc AS [Compte comptable], F_COMPTET.CT_Contact AS [Contact], F_COMPTET.CT_Adresse AS [Adresse], F_COMPTET.CT_Complement AS [Complément], F_COMPTET.CT_CodePostal AS [Code postal], F_COMPTET.CT_Ville AS Ville, F_COMPTET.CT_CodeRegion AS [Région], F_COMPTET.CT_Pays AS [Pays], F_COMPTET.CT_Telephone AS Téléphone, F_COMPTET.CT_EMail AS Email, F_COMPTET.cbCreation [Date de création], F_COMPTET.cbModification [Date de modification] FROM F_COMPTET LEFT OUTER JOIN F_COMPTET AS F_COMPTET_1 ON F_COMPTET.CT_NumPayeur = F_COMPTET_1.CT_Num LEFT OUTER JOIN P_CRISQUE ON F_COMPTET.N_Risque = P_CRISQUE.cbIndice LEFT OUTER JOIN F_COLLABORATEUR ON F_COMPTET.CO_No = F_COLLABORATEUR.CO_No LEFT OUTER JOIN F_DEPOT ON F_COMPTET.DE_No = F_DEPOT.DE_No LEFT OUTER JOIN P_DEVISE ON F_COMPTET.N_Devise = P_DEVISE.cbIndice LEFT OUTER JOIN P_CATTARIF ON F_COMPTET.N_CatTarif = P_CATTARIF.cbIndice WHERE (F_COMPTET.CT_Type = 0)',
N'Clients', N'Code client', N'DB', 'incremental', N'Date de modification', 'high', 5, 1);

-- 5. Lignes des ventes (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Lignes des ventes',
N'SELECT DL_No [N° interne], ISNULL( CASE F_DOCENTETE.DO_Type WHEN 0 THEN ''Devis'' WHEN 1 THEN ''Bon de commande'' WHEN 2 THEN ''Préparation de livraison'' WHEN 3 THEN ''Bon de livraison'' WHEN 4 THEN ''Bon de retour'' WHEN 5 THEN ''Bon avoir financier'' WHEN 6 THEN CASE DO_Provenance WHEN 0 THEN ''Facture'' WHEN 1 THEN ''Facture de retour'' WHEN 2 THEN ''Facture avoir'' WHEN 3 THEN ''Facture caisse décentralisée'' when 4 then ''Facture d''''accompte'' END WHEN 7 THEN CASE DO_Provenance WHEN 0 THEN ''Facture comptabilisée'' WHEN 1 THEN ''Facture de retour comptabilisée'' WHEN 2 THEN ''Facture avoir comptabilisée'' WHEN 3 THEN ''Facture caisse décentralisée comptabilisée'' WHEN 4 THEN ''Facture d''''accompte comptabilisée'' END WHEN 8 THEN ''Archive'' ELSE ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'' END , '''' ) AS [Type Document], CASE WHEN F_DOCLIGNE.DO_Type < 3 THEN ''Non'' ELSE ''Oui'' END AS [Valorise CA], F_DOCENTETE.DO_Tiers AS [Code client], F_COMPTET.CT_Intitule AS [Intitulé client], ISNULL(F_DOCLIGNE.DO_Piece, '''') AS [N° Pièce], F_DOCLIGNE.DO_Ref AS Référence, ( SELECT top 1 CA_Intitule FROM F_COMPTEA WHERE F_COMPTEA.CA_Num=f_docligne.ca_num) AS [Intitulé affaire], f_docligne.CA_Num AS [Code d''affaire], CONVERT(DATETIME, F_DOCENTETE.DO_Date, 3) AS [Date], CONVERT(DATETIME, F_DOCENTETE.DO_Date, 3) AS [Date document], CASE WHEN F_DOCLIGNE.DO_Type = 3 THEN F_DOCLIGNE.DO_Piece WHEN F_DOCLIGNE.DO_Type > 3 THEN F_DOCLIGNE.DL_PieceBL END AS [N° Pièce BL], CASE WHEN F_DOCLIGNE.DO_Type = 3 THEN F_DOCLIGNE.DO_Date WHEN F_DOCLIGNE.DO_Type > 3 THEN CASE WHEN F_DOCLIGNE.DL_DateBL < 0 THEN ''01/01/1900'' ELSE F_DOCLIGNE.DL_DateBL END END AS [Date BL], CASE F_DOCLIGNE.DO_Type WHEN 1 THEN F_DOCLIGNE.DO_Piece ELSE F_DOCLIGNE.DL_PieceBC END AS [N° Pièce BC], CASE F_DOCLIGNE.DO_Type WHEN 1 THEN F_DOCLIGNE.DO_Date ELSE F_DOCLIGNE.DL_DateBC END AS [Date BC], CASE F_DOCLIGNE.DO_Type WHEN 2 THEN F_DOCLIGNE.DO_Piece ELSE F_DOCLIGNE.DL_PieceBC END AS [N° pièce PL], CASE F_DOCLIGNE.DO_Type WHEN 2 THEN F_DOCLIGNE.DO_Date ELSE F_DOCLIGNE.DL_DatePL END AS [Date PL], CASE WHEN F_DOCLIGNE.DO_DateLivr < 0 THEN NULL ELSE F_DOCLIGNE.DO_DateLivr END AS [Date Livraison], F_DOCLIGNE.AR_Ref AS [Code article], F_DOCLIGNE.DL_Design AS [Désignation ligne], F_CATALOGUE_1.CL_Intitule AS [Catalogue 1], F_CATALOGUE.CL_Intitule AS [Catalogue 2], F_CATALOGUE_2.CL_Intitule AS [Catalogue 3], F_CATALOGUE_3.CL_Intitule AS [Catalogue 4], P_GAMME.G_Intitule AS [Gamme 1], P_GAMME_1.G_Intitule AS [Gamme 2], CASE F_DOCENTETE.DO_Colisage WHEN 0 THEN P_UNITE.U_Intitule ELSE CAST(F_DOCENTETE.DO_Colisage AS VARCHAR) + '' '' + P_UNITE.U_Intitule END AS Colisage, CAST(F_DOCLIGNE.DL_PoidsBrut / ( SELECT CASE PR_UnitePoids WHEN 0 THEN 1000000.000 WHEN 1 THEN 100000.000 WHEN 2 THEN 1000.000 WHEN 3 THEN 1.000 WHEN 4 THEN 0.001 END AS Expr1 FROM P_PREFERENCES ) AS FLOAT) AS [Poids brut], CAST(F_DOCLIGNE.DL_PoidsNet / ( SELECT CASE PR_UnitePoids WHEN 0 THEN 1000000.000 WHEN 1 THEN 100000.000 WHEN 2 THEN 1000.000 WHEN 3 THEN 1.000 WHEN 4 THEN 0.001 END AS Expr1 FROM P_PREFERENCES AS P_PREFERENCES_1 ) AS FLOAT) AS [Poids net], CASE FART.AR_SuiviStock WHEN 1 THEN CASE F_DOCLIGNE.DL_MvtStock WHEN 0 THEN ( SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoOut ) WHEN 1 THEN ( SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoIn ) WHEN 3 THEN ( SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoOut ) END WHEN 5 THEN CASE F_DOCLIGNE.DL_MvtStock WHEN 0 THEN ( SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoOut ) WHEN 1 THEN ( SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoIn ) WHEN 3 THEN ( SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoOut ) END END AS [N° Série/Lot], CASE DL_Taxe1 WHEN 0 THEN STR(DL_Taxe1) + ''%'' ELSE CASE DL_TypeTaux1 WHEN 0 THEN STR(DL_Taxe1, 6, 2) + ''%'' WHEN 1 THEN STR(DL_Taxe1, 6, 2) + ''F'' WHEN 2 THEN STR(DL_Taxe1, 6, 2) + ''U'' ELSE ''ERREUR. Contacter votre revendeur.'' END END AS Taxe1, CASE DL_Taxe2 WHEN 0 THEN STR(DL_Taxe2) + ''%'' ELSE CASE DL_TypeTaux2 WHEN 0 THEN STR(DL_Taxe2, 6, 2) + ''%'' WHEN 1 THEN STR(DL_Taxe2, 6, 2) + ''F'' WHEN 2 THEN STR(DL_Taxe2, 6, 2) + ''U'' ELSE ''ERREUR. Contacter votre revendeur.'' END END AS Taxe2, CASE DL_Taxe3 WHEN 0 THEN STR(DL_Taxe3) + ''%'' ELSE CASE DL_TypeTaux3 WHEN 0 THEN STR(DL_Taxe3, 6, 2) + ''%'' WHEN 1 THEN STR(DL_Taxe3, 6, 2) + ''F'' WHEN 2 THEN STR(DL_Taxe3, 6, 2) + ''U'' ELSE ''ERREUR. Contacter votre revendeur.'' END END AS Taxe3, CASE DL_TypeTaux1 WHEN 0 THEN ''Taux %'' WHEN 1 THEN ''Montant forfait'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taux taxe 1], CASE DL_TypeTaux2 WHEN 0 THEN ''Taux %'' WHEN 1 THEN ''Montant forfait'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taux taxe 2], CASE DL_TypeTaux3 WHEN 0 THEN ''Taux %'' WHEN 1 THEN ''Montant forfait'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taux taxe 3], CASE DL_TypeTaxe1 WHEN 0 THEN ''TVA/débit'' WHEN 1 THEN ''TVA/Encaissement'' WHEN 2 THEN ''TP/HT'' WHEN 3 THEN ''TP/TTC'' WHEN 4 THEN ''TP/Poids'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taxe 1], CASE DL_TypeTaxe2 WHEN 0 THEN ''TVA/débit'' WHEN 1 THEN ''TVA/Encaissement'' WHEN 2 THEN ''TP/HT'' WHEN 3 THEN ''TP/TTC'' WHEN 4 THEN ''TP/Poids'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taxe 2], CASE DL_TypeTaxe3 WHEN 0 THEN ''TVA/débit'' WHEN 1 THEN ''TVA/Encaissement'' WHEN 2 THEN ''TP/HT'' WHEN 3 THEN ''TP/TTC'' WHEN 4 THEN ''TP/Poids'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taxe 3], -- CAST(CAST(ROUND(F_DOCLIGNE.DL_Remise01REM_Valeur, 2) AS DECIMAL(18, 2)) AS varchar(100)) + ''%'' FORMAT(F_DOCLIGNE.DL_Remise01REM_Valeur, ''P2'') AS [Remise 1], FORMAT(F_DOCLIGNE.DL_Remise02REM_Valeur, ''P2'') AS [Remise 2], CAST(F_DOCLIGNE.DL_Frais AS FLOAT) AS [Frais d''approche], F_DOCLIGNE.DL_PUDevise AS [PU Devise], CASE [DL_Remise01REM_Type] WHEN 0 THEN ''Montant'' WHEN 1 THEN ''Pourcentage'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type de la remise 1], CASE [DL_Remise02REM_Type] WHEN 0 THEN ''Montant'' WHEN 1 THEN ''Pourcentage'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type de la remise 2], AC_RefClient [Référence article client], DL_FactPoids [Article facturé au poids], CASE DL_TNomencl WHEN 0 THEN ''Oui'' WHEN 1 THEN ''Non'' ELSE '' ERREUR - Contactez votre revendeur.'' END AS Nomenclature, CASE DL_TRemPied WHEN 0 THEN ''Oui'' WHEN 1 THEN ''Non'' ELSE '' ERREUR - Contactez votre revendeur.'' END AS [Type remise de pied], CASE DL_TRemExep WHEN 0 THEN ''Oui'' WHEN 1 THEN ''Non'' ELSE '' ERREUR - Contactez votre revendeur.'' END AS [Type remise exceptionnelle], F_DOCLIGNE.DL_CMUP AS CMUP, F_DOCLIGNE.DL_PrixUnitaire AS [Prix unitaire], F_DOCLIGNE.DL_PUTTC AS [Prix unitaire TTC], DL_PUBC [Prix unitaire BC], EU_Enumere Conditionnement, CASE WHEN F_DOCLIGNE.DO_Type <> 5 AND F_DOCLIGNE.DO_Type <> 15 AND DL_TRemPied = 0 AND DL_TRemExep = 0 AND DL_TypePL < 2 AND AR_FactForfait = 0 THEN CASE WHEN (F_DOCLIGNE.DO_Domaine = 4) THEN 0 ELSE CASE WHEN ( F_DOCLIGNE.DO_Type = 4 OR F_DOCLIGNE.DO_Type = 14 ) THEN -DL_Qte ELSE DL_Qte END END ELSE 0 END AS [Quantité], F_DOCLIGNE.DL_QtePL AS [Quantité PL], DL_QteBC [Quantité BC],DL_QteBL [Quantité BL], DL_QteDE [Quantité devis], CASE WHEN ( ( F_DOCLIGNE.DO_Type >= 4 AND F_DOCLIGNE.DO_Type <= 5 ) OR ( F_DOCLIGNE.DO_Type >= 14 AND F_DOCLIGNE.DO_Type <= 15 ) ) THEN -DL_MontantHT ELSE DL_MontantHT END AS [Montant HT Net], CASE WHEN ( ( F_DOCLIGNE.DO_Type >= 4 AND F_DOCLIGNE.DO_Type <= 5 ) OR ( F_DOCLIGNE.DO_Type >= 14 AND F_DOCLIGNE.DO_Type <= 15 ) ) THEN -DL_MontantTTC ELSE DL_MontantTTC END AS [Montant TTC Net],DL_PrixRU [Prix de revient],F_DOCLIGNE.DE_No [Code dépôt] ,De_intitule [Intitulé dépôt], F_DOCLIGNE.cbCreation [Date création], F_DOCLIGNE.cbModification [Date modification] ,cast(0 as float)[DPA-Période] ,cast(0 as float) [DPA-Vente] ,cast(0 as float)[Coût standard] FROM F_DOCLIGNE INNER JOIN F_ARTICLE AS FART ON F_DOCLIGNE.cbAR_Ref = FART.cbAR_Ref INNER JOIN F_DOCENTETE ON F_DOCLIGNE.DO_Type = F_DOCENTETE.DO_Type AND F_DOCLIGNE.DO_Piece = F_DOCENTETE.DO_Piece INNER JOIN F_COMPTET ON F_DOCENTETE.cbDO_Tiers = F_COMPTET.cbCT_Num INNER JOIN F_FAMILLE ON FART.FA_CodeFamille = F_FAMILLE.FA_CodeFamille LEFT OUTER JOIN F_COMPTET AS F_COMPTET_1 ON F_COMPTET.CT_NumPayeur = F_COMPTET_1.CT_Num LEFT OUTER JOIN P_GAMME AS P_GAMME_1 ON F_DOCLIGNE.AG_No2 = P_GAMME_1.cbIndice LEFT OUTER JOIN P_GAMME ON F_DOCLIGNE.AG_No1 = P_GAMME.cbIndice LEFT OUTER JOIN F_DEPOT ON F_DOCLIGNE.DE_No = F_DEPOT.DE_No LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_3 ON FART.CL_No4 = F_CATALOGUE_3.CL_No LEFT OUTER JOIN F_CATALOGUE ON FART.CL_No2 = F_CATALOGUE.CL_No LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_2 ON FART.CL_No3 = F_CATALOGUE_2.CL_No LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_1 ON FART.CL_No1 = F_CATALOGUE_1.CL_No LEFT OUTER JOIN P_DEVISE ON F_DOCENTETE.DO_Devise = P_DEVISE.cbIndice LEFT OUTER JOIN P_UNITE ON F_DOCENTETE.DO_TypeColis = P_UNITE.cbIndice WHERE (F_DOCLIGNE.DO_Domaine = 0) AND (F_DOCLIGNE.DL_TRemExep < 2) AND (F_DOCLIGNE.DL_NonLivre = 0)',
N'Lignes_des_ventes', N'N° interne', N'DB', 'incremental', N'Date modification', 'high', 10, 0);

-- ─────────────────────────────────────────────────────────────────
-- PRIORITE NORMAL - VENTES (6 tables)
-- ─────────────────────────────────────────────────────────────────

-- 6. Lieu de livraison clients (FULL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Lieu de livraison clients',
N'SELECT F_LIVRAISON.LI_No [N° interne], F_LIVRAISON.CT_Num AS [Code client], F_LIVRAISON.LI_Intitule AS [Intitule livraison], ISNULL(F_LIVRAISON.LI_Adresse, '''') + ISNULL(F_LIVRAISON.LI_Complement, '''') AS Adresse, F_LIVRAISON.LI_CodePostal AS [Code postal], F_LIVRAISON.LI_Ville AS Ville, F_LIVRAISON.LI_CodeRegion AS Région, F_LIVRAISON.LI_Pays AS Pays, F_LIVRAISON.LI_Contact AS Contact, CASE WHEN LI_Principal = 1 THEN ''Oui'' ELSE ''Non'' END AS [Dépôt principal], F_LIVRAISON.LI_Telephone AS Téléphone, F_LIVRAISON.LI_Telecopie AS Fax, F_LIVRAISON.LI_EMail AS Email, P_EXPEDITION.E_Intitule AS Expédition, P_CONDLIVR.C_Intitule [Condition de livraison] FROM F_LIVRAISON INNER JOIN P_EXPEDITION ON F_LIVRAISON.N_Expedition = P_EXPEDITION.cbIndice INNER JOIN P_CONDLIVR ON F_LIVRAISON.N_Condition = P_CONDLIVR.cbIndice',
N'Lieu_Livraison_Client', N'N° interne', N'DB', 'full', NULL, 'normal', 6, 1);

-- 7. Entetes des ventes (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Entêtes des ventes',
N'SELECT F_DOCENTETE.cbMarq [N° interne], case when F_DOCENTETE.DO_Type between 0 and 6 then ''Oui'' else ''Non'' end as Encours, isnull( case F_DOCENTETE.DO_Type when 0 then ''Devis'' when 1 then ''Bon de commande'' when 2 then ''Préparation de livraison'' when 3 then ''Bon de livraison'' when 4 then ''Bon de retour'' when 5 then ''Bon avoir financier'' when 6 then case DO_Provenance when 0 then ''Facture'' when 1 then ''Facture de retour'' when 2 then ''Facture avoir'' when 3 then ''Facture caisse décentralisée'' when 4 then ''Facture d''''accompte'' end when 7 then case DO_Provenance when 0 then ''Facture comptabilisée'' when 1 then ''Facture de retour comptabilisée'' when 2 then ''Facture avoir comptabilisée'' when 3 then ''Facture caisse décentralisée comptabilisée'' when 4 then ''Facture d''''accompte comptabilisée'' end when 8 then ''Archive'' else ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'' end, ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'') as [Type Document], (select S_Intitule from dbo.P_SOUCHEVENTE where cbIndice = DO_Souche + 1) Souche, case when DO_Domaine = 1 then case when F_DOCENTETE.DO_Type = 10 then case DO_Statut when 0 then ''Saisi'' when 1 then ''Confermé'' when 2 then ''Accepté'' end else case when F_DOCENTETE.DO_Type = 11 and DO_Statut = 2 then ''Accepté'' when F_DOCENTETE.DO_Type = 12 and DO_Statut = 2 then ''Envoyé'' when F_DOCENTETE.DO_Type = 13 and DO_Statut = 2 then ''Réceptionné'' when F_DOCENTETE.DO_Type = 14 and DO_Statut = 2 then ''Facturé'' when F_DOCENTETE.DO_Type = 15 and DO_Statut = 2 then ''Facturé'' when F_DOCENTETE.DO_Type = 16 and DO_Statut = 2 then ''A comptabiliser'' when F_DOCENTETE.DO_Type = 17 and DO_Statut = 2 then ''Comptabilisé'' when F_DOCENTETE.DO_Type = 18 and DO_Statut = 2 then ''Archivé'' when DO_Statut = 0 then ''Saisie'' when DO_Statut = 1 then ''Confirmé'' else ''Contactez votre revendeur.'' end end else case when F_DOCENTETE.DO_Type = 0 and F_DOCENTETE.DO_Statut = 2 then ''Accepté'' when F_DOCENTETE.DO_Type = 1 and F_DOCENTETE.DO_Statut = 2 then ''A préparer'' when F_DOCENTETE.DO_Type = 2 and F_DOCENTETE.DO_Statut = 2 then ''A livrer'' when F_DOCENTETE.DO_Type = 3 and F_DOCENTETE.DO_Statut = 2 then ''A facturer'' when F_DOCENTETE.DO_Type = 4 and F_DOCENTETE.DO_Statut = 2 then ''A facturer'' when F_DOCENTETE.DO_Type = 5 and F_DOCENTETE.DO_Statut = 2 then ''A facturer'' when F_DOCENTETE.DO_Type = 6 and F_DOCENTETE.DO_Statut = 2 then ''A comptabiliser'' when F_DOCENTETE.DO_Type = 7 and F_DOCENTETE.DO_Statut = 2 then ''Comptabilisé'' when F_DOCENTETE.DO_Type = 8 and F_DOCENTETE.DO_Statut = 2 then ''Archivé'' when F_DOCENTETE.DO_Statut = 0 then ''Saisie'' when F_DOCENTETE.DO_Statut = 1 then ''Confirmé'' else ''ERREUR. Contactez votre revendeur.'' end end as Statut, F_DOCENTETE.DO_Tiers as [Code client], F_COMPTET.CT_Intitule as [Intitulé client], F_DOCENTETE.CO_No [Code représentant], CO_Nom+'' ''+CO_Prenom [Nom représentant], convert(datetime, F_DOCENTETE.DO_Date, 3) as [Date], isnull(F_DOCENTETE.DO_Piece, '''') as [N° pièce], case when F_DOCENTETE.DO_Ventile = 0 then ''Non'' else ''Oui'' end as [Document ventilé], case when F_DOCENTETE.DO_Reliquat = 1 then ''Reliquat'' when F_DOCENTETE.DO_Reliquat = 0 and F_DOCENTETE.DO_Imprim = 1 then ''Imprimé'' when F_DOCENTETE.DO_Reliquat = 0 and F_DOCENTETE.DO_Imprim = 0 then '' '' else ''ERREUR. Contactez votre revendeur.'' end as Etat, F_DOCENTETE.DO_Coord01 as [Entête 1], F_DOCENTETE.DO_Coord02 as [Entête 2], F_DOCENTETE.DO_Coord03 as [Entête 3], F_DOCENTETE.DO_Coord04 as [Entête 4], F_DOCENTETE.CT_NumPayeur as [N° Compte Payeur], F_COMPTET_1.CT_Intitule as [Intitulé tiers payeur], F_DEPOT.DE_Intitule as Dépôt, isnull(P_DEVISE.D_Intitule, ''Aucune'') as Devise, P_EXPEDITION.E_Intitule as Expédition, case (F_DOCENTETE.DO_Langue) when 0 then ''Aucune'' when 1 then ''Langue 1'' when 2 then ''Langue 2'' end as Langue, case F_DOCENTETE.DO_BLFact when 1 then ''Oui'' when 0 then ''Non'' end as [Fact/BL], F_DOCENTETE.DO_NbFacture as [Nb Facture], F_DOCENTETE.CG_Num as [Compte Général], F_DOCENTETE.CA_Num [Code d''affaire], ( select top 1 CA_Intitule from F_COMPTEA where F_COMPTEA.CA_Num = F_DOCENTETE.CA_Num) as [Intitulé affaire], case F_DOCENTETE.N_CatCompta when 1 then (select P_CATCOMPTA.CA_ComptaVen01 from P_CATCOMPTA) when 2 then (select P_CATCOMPTA.CA_ComptaVen02 from P_CATCOMPTA) when 3 then (select P_CATCOMPTA.CA_ComptaVen03 from P_CATCOMPTA) when 4 then (select P_CATCOMPTA.CA_ComptaVen04 from P_CATCOMPTA) when 5 then (select P_CATCOMPTA.CA_ComptaVen05 from P_CATCOMPTA) when 6 then (select P_CATCOMPTA.CA_ComptaVen06 from P_CATCOMPTA) when 7 then (select P_CATCOMPTA.CA_ComptaVen07 from P_CATCOMPTA) when 8 then (select P_CATCOMPTA.CA_ComptaVen08 from P_CATCOMPTA) when 9 then (select P_CATCOMPTA.CA_ComptaVen09 from P_CATCOMPTA) when 10 then (select P_CATCOMPTA.CA_ComptaVen10 from P_CATCOMPTA) else '' '' end as [Catégorie Comptable], F_DEPOT.DE_No as [Code dépôt], F_DOCENTETE.DO_Ref as Référence, F_DOCENTETE.DO_Cours as Cours, F_DOCENTETE.DO_TxEscompte as [Taux escompte], case when DO_Reliquat = 0 then ''Reliquet'' else ''Non'' end as [Document de reliquat], case when DO_Imprim = 0 then ''Oui'' else ''Non'' end as [Document imprimé ], F_DOCENTETE.DO_DateLivr as [Date livraison souhite], F_DOCENTETE.DO_DebutAbo as [Date début de l’abonnement lié], F_DOCENTETE.DO_FinAbo as [Date fin de l’abonnement lié], F_DOCENTETE.DO_DebutPeriod as [Date début de la périodicité liée], F_DOCENTETE.DO_FinPeriod as [Date Fin de la périodicité liée], F_DOCENTETE.DO_Cloture as [Document clôturé], case DO_TypeFrais when 0 then ''Montant Forfaitaire'' when 1 then ''Quantité'' when 2 then ''Poids net'' when 3 then ''Poids brut'' else ''Erreur. Contactez votre revendeur.'' end as [Type frais], F_DOCENTETE.DO_ValFrais as [Valeur frais], case when DO_TypeLigneFrais = 0 then ''HT'' else ''TTC'' end as [Type HT/TTC frais], case when DO_Valide = 0 then ''Oui'' else ''Non'' end as [Statut validé], P_DEVISE.D_Intitule as [Intitulé Devise], P_CATTARIF.CT_Intitule as [Catégorie tarifaire ], P_CONDLIVR.C_Intitule as [Condition de livraison], case F_DOCENTETE.DO_Colisage when 0 then P_UNITE.U_Intitule else cast(F_DOCENTETE.DO_Colisage as varchar) + '' '' + P_UNITE.U_Intitule end as Colisage, F_DOCENTETE.DO_TotalHT as [Montant HT], F_DOCENTETE.DO_TotalTTC [Montant TTC], F_DOCENTETE.DO_NetAPayer [Montant net à payer], F_DOCENTETE.DO_MontantRegle [Montant réglé], F_LIVRAISON.LI_No as [Code lieu de livraison], F_LIVRAISON.LI_Intitule [Lieu de livraison], F_DOCENTETE.cbCreation [Date création], F_DOCENTETE.cbModification [Date modification] , CASE WHEN F_DOCENTETE.DO_Type < 3 THEN ''Non'' ELSE ''Oui'' END AS [Valorise CA] from F_DEPOT inner join F_COMPTET inner join F_DOCENTETE on F_COMPTET.cbCT_Num = F_DOCENTETE.cbDO_Tiers on F_DEPOT.DE_No = F_DOCENTETE.DE_No left outer join F_COMPTET as F_COMPTET_1 on F_DOCENTETE.CT_NumPayeur = F_COMPTET_1.CT_Num left outer join F_COLLABORATEUR as COLLABORATEUR_DOC on F_DOCENTETE.cbCO_No = COLLABORATEUR_DOC.CO_No left outer join F_LIVRAISON ON F_DOCENTETE.cbLI_No = F_LIVRAISON.LI_No LEFT OUTER JOIN P_CONDLIVR ON F_DOCENTETE.DO_DateLivr = P_CONDLIVR.cbIndice LEFT OUTER JOIN P_CATTARIF ON F_DOCENTETE.DO_Tarif = P_CATTARIF.cbIndice LEFT OUTER JOIN P_DEVISE ON F_DOCENTETE.DO_Devise = P_DEVISE.cbIndice LEFT OUTER JOIN P_EXPEDITION ON F_DOCENTETE.DO_Expedit = P_EXPEDITION.cbIndice LEFT OUTER JOIN P_UNITE ON F_DOCENTETE.DO_TypeColis = P_UNITE.cbIndice WHERE (F_DOCENTETE.DO_Domaine IN ( 0 ))',
N'Entête_des_ventes', N'N° Pièce', N'DB', 'incremental', N'Date modification', 'normal', 7, 1);

-- 8. Reglements clients (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Règlements clients',
N'SELECT ISNULL(F_CREGLEMENT.CT_NumPayeur, '''') AS [Code client], F_COMPTET_1.CT_Intitule AS Intitulé, F_CREGLEMENT.CT_NumPayeurOrig AS [Code client original], F_COMPTET.CT_Intitule AS [Intitulé original], F_CREGLEMENT.RG_Date AS Date, F_CREGLEMENT.RG_DateEchCont AS [Date d''échéance], F_CREGLEMENT.RG_Reference AS Référence, F_CREGLEMENT.RG_Libelle AS Libellé, CASE WHEN F_CREGLEMENT.RG_Impute = 0 THEN ''Non'' ELSE ''Oui'' END AS Impute, CASE WHEN F_CREGLEMENT.RG_Compta = 0 THEN ''Non'' ELSE ''Oui'' END AS Comptabilisé, F_CREGLEMENT.JO_Num AS [Code journal], F_JOURNAUX.JO_Intitule AS Journal, F_CREGLEMENT.CG_Num AS [Compte générale], F_CREGLEMENT.RG_Piece AS [N° piéce], CASE WHEN F_CREGLEMENT.RG_Valide = 0 THEN ''Non'' ELSE ''Oui'' END AS Valide, P_REGLEMENT.R_Intitule AS [Mode de règlement], ISNULL(P_DEVISE.D_Intitule, ''Aucune'') AS Devise, F_CREGLEMENT.RG_MontantDev AS [Montant en devise], F_CREGLEMENT.RG_Cours AS Cours, F_CREGLEMENT.RG_Montant AS Montant, ISNULL(RG_No, '''') [N° interne], F_CREGLEMENT.RG_Montant-isnull((select sum(RC_Montant) from F_REGLECH where F_REGLECH.rg_no=F_CREGLEMENT.RG_No),0) solde, r_code [Code règlement], F_CREGLEMENT.cbCreation [Date création], F_CREGLEMENT.cbModification [Date modification] FROM F_CREGLEMENT INNER JOIN F_COMPTET AS F_COMPTET_1 ON F_CREGLEMENT.CT_NumPayeur = F_COMPTET_1.CT_Num INNER JOIN F_COMPTET ON F_CREGLEMENT.CT_NumPayeurOrig = F_COMPTET.CT_Num INNER JOIN F_JOURNAUX ON F_CREGLEMENT.JO_Num = F_JOURNAUX.JO_Num LEFT OUTER JOIN P_REGLEMENT ON F_CREGLEMENT.N_Reglement = P_REGLEMENT.cbIndice LEFT OUTER JOIN P_DEVISE ON F_CREGLEMENT.N_Devise = P_DEVISE.cbIndice WHERE (F_CREGLEMENT.RG_Type = 0)',
N'Règlements_Clients', N'N° interne', N'DB', 'incremental', N'Date modification', 'normal', 8, 1);

-- 9. Imputation factures ventes (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Imputation les factures des ventes',
N'SELECT F_CREGLEMENT.RG_Reference AS Référence, F_CREGLEMENT.RG_Libelle AS Libellé, F_REGLECH.RG_No [id Règlement], F_CREGLEMENT.RG_Date AS [Date règlement], F_CREGLEMENT.RG_DateEchCont AS [Date d''échéance], F_REGLECH.DR_No AS [Id échéance], CASE WHEN F_DOCENTETE.do_domaine = 1 THEN CASE F_DOCENTETE.DO_TYPE WHEN 10 THEN ''Demande d''''achat'' WHEN 11 THEN ''Bon de commande'' WHEN 12 THEN ''Préparation de livraison'' WHEN 13 THEN ''Bon de livraison'' WHEN 14 THEN ''Bon de retour'' WHEN 15 THEN ''Bon avoir financier'' WHEN 16 THEN CASE DO_PROVENANCE WHEN 0 THEN ''Facture'' WHEN 1 THEN ''Facture de retour'' WHEN 2 THEN ''Facture avoir'' WHEN 3 THEN ''Facture caisse décentralisée'' END WHEN 17 THEN CASE DO_PROVENANCE WHEN 0 THEN ''Facture comptabilisée'' WHEN 1 THEN ''Facture de retour comptabilisée'' WHEN 2 THEN ''Facture avoir comptabilisée'' WHEN 3 THEN ''Facture caisse décentralisée comptabilisée'' END WHEN 18 THEN ''Archive'' ELSE ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'' END ELSE CASE F_DOCENTETE.DO_TYPE WHEN 0 THEN ''Devis'' WHEN 1 THEN ''Bon de commande'' WHEN 2 THEN ''Préparation de livraison'' WHEN 3 THEN ''Bon de livraison'' WHEN 4 THEN ''Bon de retour'' WHEN 5 THEN ''Bon avoir financier'' WHEN 6 THEN CASE DO_PROVENANCE WHEN 0 THEN ''Facture'' WHEN 1 THEN ''Facture de retour'' WHEN 2 THEN ''Facture avoir'' WHEN 3 THEN ''Facture caisse décentralisée'' when 4 then ''Facture d''''accompte'' END WHEN 7 THEN CASE DO_PROVENANCE WHEN 0 THEN ''Facture comptabilisée'' WHEN 1 THEN ''Facture de retour comptabilisée'' WHEN 2 THEN ''Facture avoir comptabilisée'' WHEN 3 THEN ''Facture caisse décentralisée comptabilisée'' when 4 then ''Facture d''''accompte comptabilisée'' END WHEN 8 THEN ''Archive'' ELSE ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'' END END AS [Type Document], F_REGLECH.DO_Piece AS [N° pièce], ( SELECT SUM(DL_MontantTTC) AS Expr1 FROM F_DOCLIGNE AS ligne WHERE (DO_Type = F_REGLECH.DO_Type) AND (DO_Piece = F_REGLECH.DO_Piece) ) AS [Montant facture TTC], F_REGLECH.RC_Montant AS [Montant régler], F_DOCENTETE.DO_Date AS [Date document], P_REGLEMENT.R_Intitule AS [Mode de réglement], F_DOCENTETE.DO_Tiers AS [Code client], F_COMPTET_1.CT_Intitule AS [Intitulé client], F_COMPTET.CT_Num [Code tier payeur], F_COMPTET.CT_Intitule [Intitulé tier payeur], RG_Montant [Montant réglement], F_REGLECH.cbCreation [Date création], F_REGLECH.cbModification [Date modification] FROM F_REGLECH INNER JOIN F_DOCENTETE ON F_REGLECH.DO_Type = F_DOCENTETE.DO_Type AND F_REGLECH.DO_Piece = F_DOCENTETE.DO_Piece INNER JOIN F_COMPTET AS F_COMPTET_1 ON F_DOCENTETE.DO_Tiers = F_COMPTET_1.CT_Num INNER JOIN F_COMPTET ON F_DOCENTETE.CT_NumPayeur = F_COMPTET.CT_Num INNER JOIN F_CREGLEMENT ON F_REGLECH.RG_No = F_CREGLEMENT.RG_No INNER JOIN P_REGLEMENT ON F_CREGLEMENT.N_Reglement = P_REGLEMENT.cbIndice WHERE (F_DOCENTETE.DO_Domaine = 0)',
N'Imputation_Factures_Ventes', NULL, N'DB', 'incremental', N'Date modification', 'normal', 9, 0);

