-- 11. Echeances ventes (FULL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Echéances ventes',
N'with Cte_Lignes as (select l.DO_Piece as [N° document] , l.DO_Date as [Date] , e.DO_Ref as Référence , l.DL_MontantHT as [Montant HT] , l.DL_MontantTTC as [Montant TTC] , e.DO_Cours as Cours , l.DL_Qte * l.DL_PUDevise as [Montant en devise] , l.DL_Taxe1 as [Taxe 1] , e.DO_TxEscompte as Escompte , e.DO_ValFrais as [Frais port] , e.CT_NumPayeur as [Code tiers payeur] , l.CT_Num as [Code client] , e.CA_Num as [Code affaire] , e.DO_Souche as Souche , e.N_CatCompta as [Catégorie comptable] , e.DO_PieceOrig as [Pièce orgine] , coalesce( case when e.DO_Type = 0 then ''Devis'' when e.DO_Type = 1 then ''Bon de commande'' when e.DO_Type = 2 then ''Préparation de livraison'' when e.DO_Type = 3 then ''Bon de livraison'' when e.DO_Type = 4 then ''Bon de retour'' when e.DO_Type = 5 then ''Bon avoir financier'' when e.DO_Type in ( 6, 7 ) then case DO_Provenance when 0 then ''Facture'' when 1 then ''Facture de retour'' when 2 then ''Facture avoir'' when 3 then ''Facture caisse décentralisée'' when 4 then ''Facture d''''accompte'' end when e.DO_Type = 8 then ''Archive'' else ''ERREUR - Contactez votre revendeur.'' end , ''ERREUR - Contactez votre revendeur.'' ) as [Type Document] -- New calculated columns: , (DL_MontantHT / sum(DL_MontantHT) over (partition by l.DO_Piece, l.DO_Type, e.DO_Provenance)) as [Poids Frais Port] , (DO_ValFrais * (DL_MontantHT / sum(DL_MontantHT) over (partition by l.DO_Piece, l.DO_Type, e.DO_Provenance))) as [Valeur frais port] , ((DL_MontantHT * (1 - DO_TxEscompte / 100)) + (DO_ValFrais * (DL_MontantHT / sum(DL_MontantHT) over (partition by l.DO_Piece, l.DO_Type, e.DO_Provenance)) ) ) as [Montant HT Net] , (((DL_MontantHT * (1 - DO_TxEscompte / 100)) + (DO_ValFrais * CASE WHEN sum(DL_MontantHT) over (partition by l.DO_Piece, l.DO_Type, e.DO_Provenance)=0 THEN 0 ELSE (DL_MontantHT / sum(DL_MontantHT) over (partition by l.DO_Piece, l.DO_Type, e.DO_Provenance) )END ) ) * (1 + DL_Taxe1 / 100) ) as [Montant TTC Net] from F_DOCLIGNE as l inner join F_DOCENTETE as e on l.DO_Type = e.DO_Type and l.DO_Piece = e.DO_Piece where (l.DO_Domaine = 0) -- and (l.DO_Type >= 6) and (l.DL_Valorise = 1)) , DocTemp as (select [Type Document] as [Type Document] , [N° document] as [N° document] , [Date] as [Date] , Référence as Référence , sum([Montant HT]) as [Montant HT] , sum([Montant TTC]) as [Montant TTC] , Cours as Cours , sum([Montant en devise]) as [Montant en devise] , Escompte as Escompte , [Frais port] as [Frais port] , [Code tiers payeur] as [Code tiers payeur] , [Code client] as [Code client] , [Code affaire] as [Code affaire] , Souche as Souche , [Catégorie comptable] as [Catégorie comptable] , [Pièce orgine] as [Pièce orgine] , sum([Montant HT Net]) as [Montant HT Net] , sum([Montant TTC Net]) as [Montant TTC Net] from Cte_Lignes group by [Type Document] , [N° document] , [Date] , Référence , Cours , Escompte , [Frais port] , [Code tiers payeur] , [Code affaire] , Souche , [Catégorie comptable] , [Pièce orgine] , [Code client]) , AcompteAgg as ( -- Pre-aggregate advance payment amounts (only for documents having DR_TypeRegl = 0) select DO_Type , DO_Piece , sum(DR_Montant) as MontantAcompte from F_DOCREGL where DR_TypeRegl = 0 group by DO_Type , DO_Piece) select dr.DR_No as [N° interne] , dt.[Code tiers payeur] as [Code tiers payeur] , tiersPayeur.CT_Intitule as [Intitulé Tiers payeur] , dt.[Code client] as [Code client] , tiers.CT_Intitule as [Intitulé client] , [Type Document] as [Type Document] , dr.DO_Piece as [N° Pièce] , [Date] as [Date document] , dr.DR_Date as [Date d''échéance] , (dt.[Montant TTC Net] - isnull(aa.MontantAcompte, 0)) as [Montant TTC Net] , [Montant en devise] as [Montant en devise] , dt.Cours as Cours , DR_Libelle as [Libellé du règlement] , case when dr.DR_Equil = 1 then (dt.[Montant TTC Net] - isnull(aa.MontantAcompte, 0)) - sum(((dt.[Montant TTC Net] - isnull(aa.MontantAcompte, 0)) * dr.DR_Pourcent / 100) + dr.DR_Montant) over (partition by dr.DO_Piece , dr.DO_Type , DR_TypeRegl order by dr.DR_Date rows between unbounded preceding and unbounded following ) when dr.DR_Pourcent is not null and dr.DR_Pourcent <> 0 then (dt.[Montant TTC Net] - isnull(aa.MontantAcompte, 0)) * dr.DR_Pourcent / 100 when dr.DR_Montant is not null and dr.DR_Montant <> 0 then dr.DR_Montant else 0 end as [Montant échéance] , dt.[Montant HT] as [Montant HT brut] , dt.[Montant TTC] as [Montant TTC brut] , case dr.DR_TypeRegl when 0 then ''Acompte'' when 1 then ''Bon d’achat'' else ''Règlement'' end as [Type de règlement] , dr.DR_Pourcent as [Pourcentage du règlement] , dr.DR_Montant as [Montant du règlement] , case when [DR_Equil] = 0 then ''Non'' else ''Oui'' end as [Ligne d’équilibrage] , dr.N_Reglement as [Code mode règlement] , R_Intitule as [Mode de règlement] ,dr.cbModification [Date modification] from F_DOCREGL dr left join DocTemp dt on dr.DO_Piece = dt.[N° document] left join AcompteAgg aa on dr.DO_Type = aa.DO_Type and dr.DO_Piece = aa.DO_Piece left join dbo.P_REGLEMENT on dr.N_Reglement = P_REGLEMENT.cbIndice left join F_COMPTET tiers on dt.[Code client] = tiers.CT_Num left join F_COMPTET tiersPayeur on dt.[Code tiers payeur] = tiersPayeur.CT_Num where dr.DO_Domaine = 0',
N'Echéances_Ventes', N'N° interne', N'DB', 'incremental', N'cbModification', 'normal', 12, 0);

