-- 12. Liste des fournisseurs (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Liste des fournisseurs',
N'SELECT F_COMPTET.CT_Qualite AS Qualité, F_COMPTET.CT_Num AS [Code fournisseur], F_COMPTET.CT_Intitule AS [Intitulé], F_COMPTET.CT_Classement AS [Classement], F_COMPTET.CO_No AS [Code acheteur], F_COLLABORATEUR.CO_Nom+'' ''+CO_Prenom AS Acheteur, F_COMPTET.CT_NumPayeur AS [Code encaisseur], F_COMPTET_1.CT_Intitule AS [Tiers encaisseur], ISNULL(P_DEVISE.D_Intitule, ''Aucune'') AS [Devise], P_CATTARIF.CT_Intitule AS [Catégorie tarifaire], ISNULL(F_DEPOT.DE_Intitule, ''Dépôt principal'') AS [Dépôt], CASE F_COMPTET.CT_Sommeil WHEN 0 THEN ''Actif'' WHEN 1 THEN ''En sommeil'' END AS [En sommeil], F_COMPTET.CG_NumPrinc AS [Compte comptable], F_COMPTET.CT_Contact AS [Contact], F_COMPTET.CT_Adresse AS [Adresse], F_COMPTET.CT_CodePostal AS [Code postal], F_COMPTET.CT_Ville AS Ville, F_COMPTET.CT_Telephone AS Téléphone, F_COMPTET.CT_EMail AS Email, F_COMPTET.cbCreation [Date de création], F_COMPTET.cbModification [Date modification] FROM F_COMPTET INNER JOIN F_COMPTET F_COMPTET_1 ON F_COMPTET.CT_NumPayeur = F_COMPTET_1.CT_Num LEFT OUTER JOIN P_CRISQUE ON F_COMPTET.N_Risque = P_CRISQUE.cbIndice LEFT OUTER JOIN F_COLLABORATEUR ON F_COMPTET.CO_No = F_COLLABORATEUR.CO_No LEFT OUTER JOIN F_DEPOT ON F_COMPTET.DE_No = F_DEPOT.DE_No LEFT OUTER JOIN P_DEVISE ON F_COMPTET.N_Devise = P_DEVISE.cbIndice LEFT OUTER JOIN P_CATTARIF ON F_COMPTET.N_CatTarif = P_CATTARIF.cbIndice WHERE (F_COMPTET.CT_Type = 1)',
N'Fournisseurs', N'Code fournisseur', N'DB', 'incremental', N'Date modification', 'normal', 14, 1);

-- 13. Entetes des achats (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Entêtes des achats',
N'SELECT ISNULL(CASE F_DOCENTETE.DO_Type WHEN 10 THEN ''Demande d''''achat'' WHEN 11 THEN ''Préparation de commande'' WHEN 12 THEN ''Bon de commande'' WHEN 13 THEN ''Bon de livraison'' WHEN 14 THEN ''Bon de retour'' WHEN 15 THEN ''Bon avoir financier'' WHEN 16 THEN CASE DO_Provenance WHEN 0 THEN ''Facture'' WHEN 1 THEN ''Facture de retour'' WHEN 2 THEN ''Facture avoir'' WHEN 3 THEN ''Facture caisse décentralisée'' WHEN 4 THEN ''Facture d"accompte'' END WHEN 17 THEN CASE DO_Provenance WHEN 0 THEN ''Facture comptabilisée'' WHEN 1 THEN ''Facture de retour comptabilisée'' WHEN 2 THEN ''Facture avoir comptabilisée'' WHEN 3 THEN ''Facture caisse décentralisée comptabilisée'' WHEN 4 THEN ''Facture d"accompte comptabilisée'' END WHEN 18 THEN ''Archive'' ELSE ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'' END,'''') AS [Type Document], CASE WHEN F_DOCENTETE.DO_Type BETWEEN 0 AND 6 THEN ''Oui'' ELSE ''Non'' END AS Encours, CASE WHEN DO_Domaine = 1 THEN CASE WHEN F_DOCENTETE.DO_Type = 10 THEN CASE DO_Statut WHEN 0 THEN ''Saisi'' WHEN 1 THEN ''Confermé'' WHEN 2 THEN ''Accepté'' END ELSE CASE WHEN F_DOCENTETE.DO_Type = 11 AND DO_Statut = 2 THEN ''Accepté'' WHEN F_DOCENTETE.DO_Type = 12 AND DO_Statut = 2 THEN ''Envoyé'' WHEN F_DOCENTETE.DO_Type = 13 AND DO_Statut = 2 THEN ''Réceptionné'' WHEN F_DOCENTETE.DO_Type = 14 AND DO_Statut = 2 THEN ''Facturé'' WHEN F_DOCENTETE.DO_Type = 15 AND DO_Statut = 2 THEN ''Facturé'' WHEN F_DOCENTETE.DO_Type = 16 AND DO_Statut = 2 THEN ''A comptabiliser'' WHEN F_DOCENTETE.DO_Type = 17 AND DO_Statut = 2 THEN ''Comptabilisé'' WHEN F_DOCENTETE.DO_Type = 18 AND DO_Statut = 2 THEN ''Archivé'' WHEN DO_Statut = 0 THEN ''Saisie'' WHEN DO_Statut = 1 THEN ''Confirmé'' ELSE ''Contactez votre revendeur.'' END END ELSE CASE WHEN F_DOCENTETE.DO_Type = 0 AND F_DOCENTETE.DO_Statut = 2 THEN ''Accepté'' WHEN F_DOCENTETE.DO_Type = 1 AND F_DOCENTETE.DO_Statut = 2 THEN ''A préparer'' WHEN F_DOCENTETE.DO_Type = 2 AND F_DOCENTETE.DO_Statut = 2 THEN ''A livrer'' WHEN F_DOCENTETE.DO_Type = 3 AND F_DOCENTETE.DO_Statut = 2 THEN ''A facturer'' WHEN F_DOCENTETE.DO_Type = 4 AND F_DOCENTETE.DO_Statut = 2 THEN ''A facturer'' WHEN F_DOCENTETE.DO_Type = 5 AND F_DOCENTETE.DO_Statut = 2 THEN ''A facturer'' WHEN F_DOCENTETE.DO_Type = 6 AND F_DOCENTETE.DO_Statut = 2 THEN ''A comptabiliser'' WHEN F_DOCENTETE.DO_Type = 7 AND F_DOCENTETE.DO_Statut = 2 THEN ''Comptabilisé'' WHEN F_DOCENTETE.DO_Type = 8 AND F_DOCENTETE.DO_Statut = 2 THEN ''Archivé'' WHEN F_DOCENTETE.DO_Statut = 0 THEN ''Saisie'' WHEN F_DOCENTETE.DO_Statut = 1 THEN ''Confirmé'' ELSE ''ERREUR. Contactez votre revendeur.'' END END AS Statut, CASE WHEN DO_Valide = 0 THEN ''Oui'' ELSE ''Non'' END AS [Statut validé], CASE WHEN DO_Reliquat = 0 THEN ''Oui'' ELSE ''Non'' END AS [Document reliquat], CASE WHEN F_DOCENTETE.DO_Cloture = 0 THEN ''Non'' ELSE ''Oui'' END AS [Document clôturé], CONVERT(DATETIME, F_DOCENTETE.DO_Date, 3) AS Date, ISNULL(F_DOCENTETE.DO_Piece, '''') AS [N° Pièce], (SELECT S_Intitule FROM dbo.P_SOUCHEACHAT WHERE cbIndice = DO_Souche + 1) Souche, F_DOCENTETE.DO_Ref AS Référence, F_DOCENTETE.DO_Tiers AS [Code Fournisseur], F_COMPTET.CT_Intitule AS [Intitulé Fournisseur], F_DOCENTETE.CT_NumPayeur AS [N° Compte tiers encaisseur], F_COMPTET_1.CT_Intitule AS [Intitulé tiers encaisseur], F_DOCENTETE.cbCO_No [Code acheteur], COLLABORATEUR_DOC.CO_Nom+'' ''+COLLABORATEUR_DOC.CO_Prenom [Nom acheteur], CASE WHEN F_DOCENTETE.DO_Ventile = 0 THEN ''Non'' ELSE ''Oui'' END AS [Document ventilé], CASE WHEN F_DOCENTETE.DO_Reliquat = 1 THEN ''Reliquat'' WHEN F_DOCENTETE.DO_Reliquat = 0 AND F_DOCENTETE.DO_Imprim = 1 THEN ''Imprimé'' WHEN F_DOCENTETE.DO_Reliquat = 0 AND F_DOCENTETE.DO_Imprim = 0 THEN '' '' ELSE ''ERREUR. Contactez votre revendeur.'' END AS Etat, F_DOCENTETE.DO_Coord01 AS [Entête 1], F_DOCENTETE.DO_Coord02 AS [Entête 2], F_DOCENTETE.DO_Coord03 AS [Entête 3], F_DOCENTETE.DO_Coord04 AS [Entête 4], F_DEPOT.DE_No AS [Code dépôt], F_DEPOT.DE_Intitule AS [Intitulé dépôt], ISNULL(P_DEVISE.D_Intitule, ''Aucune'') AS Devise, F_DOCENTETE.DO_Cours AS Cours, P_EXPEDITION.E_Intitule AS Expédition, CASE (F_DOCENTETE.DO_Langue) WHEN 0 THEN ''Aucune'' WHEN 1 THEN ''Langue 1'' WHEN 2 THEN ''Langue 2'' END AS Langue, CASE F_DOCENTETE.DO_BLFact WHEN 1 THEN ''Oui'' WHEN 0 THEN ''Non'' END AS [Fact/BL], F_DOCENTETE.DO_NbFacture AS [Nb Facture], F_DOCENTETE.CA_Num [Code d''affaire], ( SELECT TOP 1 CA_Intitule FROM F_COMPTEA WHERE F_COMPTEA.CA_Num = F_DOCENTETE.ca_num) AS [Intitulé affaire], F_DOCENTETE.CG_Num AS [Compte Général], CASE F_DOCENTETE.N_CatCompta WHEN 1 THEN (SELECT P_CATCOMPTA.CA_ComptaVen01 FROM P_CATCOMPTA) WHEN 2 THEN (SELECT P_CATCOMPTA.CA_ComptaVen02 FROM P_CATCOMPTA) WHEN 3 THEN (SELECT P_CATCOMPTA.CA_ComptaVen03 FROM P_CATCOMPTA) WHEN 4 THEN (SELECT P_CATCOMPTA.CA_ComptaVen04 FROM P_CATCOMPTA) WHEN 5 THEN (SELECT P_CATCOMPTA.CA_ComptaVen05 FROM P_CATCOMPTA) WHEN 6 THEN (SELECT P_CATCOMPTA.CA_ComptaVen06 FROM P_CATCOMPTA) WHEN 7 THEN (SELECT P_CATCOMPTA.CA_ComptaVen07 FROM P_CATCOMPTA) WHEN 8 THEN (SELECT P_CATCOMPTA.CA_ComptaVen08 FROM P_CATCOMPTA) WHEN 9 THEN (SELECT P_CATCOMPTA.CA_ComptaVen09 FROM P_CATCOMPTA) WHEN 10 THEN (SELECT P_CATCOMPTA.CA_ComptaVen10 FROM P_CATCOMPTA) ELSE '' '' END AS [Catégorie Comptable], CASE F_DOCENTETE.DO_Colisage WHEN 0 THEN P_UNITE.U_Intitule ELSE CAST(F_DOCENTETE.DO_Colisage AS VARCHAR) + '' '' + P_UNITE.U_Intitule END AS Colisage, F_DOCENTETE.DO_TxEscompte AS [Taux escompte], DO_Ecart [Ecart], CASE WHEN DO_Imprim = 0 THEN ''Oui'' ELSE ''Non'' END AS [Document imprimé ], F_DOCENTETE.DO_DateLivr AS [Date livraison souhaite], F_DOCENTETE.DO_DebutAbo AS [Date début de l’abonnement lié], F_DOCENTETE.DO_FinAbo AS [Date fin de l’abonnement lié], F_DOCENTETE.DO_DebutPeriod AS [Date début de la périodicité liée], F_DOCENTETE.DO_FinPeriod AS [Date Fin de la périodicité liée], F_DOCENTETE.DO_FactureFrs AS [N° facture Fournisseur], CASE DO_TypeFrais WHEN 0 THEN ''Montant Forfaitaire'' WHEN 1 THEN ''Quantité'' WHEN 2 THEN ''Poids net'' WHEN 3 THEN ''Poids brut'' ELSE ''Erreur. Contactez votre revendeur.'' END AS [Type frais], F_DOCENTETE.DO_ValFrais AS [Valeur frais], CASE WHEN DO_TypeLigneFrais = 0 THEN ''HT'' ELSE ''TTC'' END AS [Type HT/TTC frais], P_CATTARIF.CT_Intitule AS [Catégorie tarifaire ], P_CONDLIVR.C_Intitule AS [Condition de livraison], LI_No [Code lieu de livraison], ( SELECT liv.LI_Intitule FROM dbo.F_LIVRAISON liv WHERE liv.LI_No = F_DOCENTETE.LI_No) [Lieu de livraison], F_DOCENTETE.DO_TotalHT AS [Montant HT], F_DOCENTETE.DO_TotalTTC [Montant TTC], F_DOCENTETE.DO_NetAPayer [Montant net à payer], F_DOCENTETE.DO_MontantRegle [Montant réglé],'''' [Souche Ach. Imoprt], F_DOCENTETE.cbCreation [Date création], F_DOCENTETE.cbModification [Date modification] FROM F_COMPTET AS F_COMPTET_1 INNER JOIN F_COMPTET INNER JOIN F_DOCENTETE ON F_COMPTET.cbCT_Num = F_DOCENTETE.cbDO_Tiers ON F_COMPTET_1.CT_Num = F_COMPTET.CT_NumPayeur LEFT OUTER JOIN F_DEPOT ON F_DOCENTETE.DE_No = F_DEPOT.DE_No LEFT OUTER JOIN P_CONDLIVR ON F_DOCENTETE.DO_DateLivr = P_CONDLIVR.cbIndice LEFT OUTER JOIN P_CATTARIF ON F_DOCENTETE.DO_Tarif = P_CATTARIF.cbIndice LEFT OUTER JOIN F_COLLABORATEUR AS COLLABORATEUR_TIERS ON F_COMPTET.CO_No = COLLABORATEUR_TIERS.CO_No LEFT OUTER JOIN F_COLLABORATEUR AS COLLABORATEUR_DOC ON F_DOCENTETE.cbCO_No = COLLABORATEUR_DOC.CO_No LEFT OUTER JOIN P_DEVISE ON F_DOCENTETE.DO_Devise = P_DEVISE.cbIndice LEFT OUTER JOIN P_EXPEDITION ON F_DOCENTETE.DO_Expedit = P_EXPEDITION.cbIndice LEFT OUTER JOIN P_UNITE ON F_DOCENTETE.DO_TypeColis = P_UNITE.cbIndice WHERE (F_DOCENTETE.DO_Domaine IN ( 1 ))',
N'Entête_des_achats', N'N° Pièce', N'DB', 'incremental', N'Date modification', 'normal', 15, 1);

-- 14. Reglements fournisseurs (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Réglements fournisseurs',
N'SELECT ISNULL(F_CREGLEMENT.CT_NumPayeur, '''') AS [Code fournisseur], F_COMPTET_1.CT_Intitule AS Intitulé, F_CREGLEMENT.RG_Date AS Date, F_CREGLEMENT.RG_DateEchCont AS [Date d''échéance], F_CREGLEMENT.RG_Reference AS Référence, F_CREGLEMENT.RG_Libelle AS Libellé, CASE WHEN F_CREGLEMENT.RG_Impute = 0 THEN ''Non'' ELSE ''Oui'' END AS Impute, CASE WHEN F_CREGLEMENT.RG_Compta = 0 THEN ''Non'' ELSE ''Oui'' END AS Comptabilisé, F_CREGLEMENT.JO_Num AS [Code journal], F_JOURNAUX.JO_Intitule AS Journal, F_CREGLEMENT.CG_Num AS [Compte générale], F_CREGLEMENT.RG_Piece AS [N° piéce], P_REGLEMENT.R_Intitule AS [Mode réglement], ISNULL(P_DEVISE.D_Intitule, ''Aucune'') AS Devise, F_CREGLEMENT.RG_MontantDev AS [Montant en devise], F_CREGLEMENT.RG_Cours AS Cours, F_CREGLEMENT.RG_Montant AS Montant, ISNULL(RG_No, '''') [N° interne], F_CREGLEMENT.RG_Montant-isnull((select sum(RC_Montant) from F_REGLECH where F_REGLECH.rg_no=F_CREGLEMENT.RG_No),0) solde, r_code [Code réglement], F_CREGLEMENT.cbCreation [Date création], F_CREGLEMENT.cbModification [Date modification] FROM F_CREGLEMENT INNER JOIN F_COMPTET AS F_COMPTET_1 ON F_CREGLEMENT.CT_NumPayeur = F_COMPTET_1.CT_Num INNER JOIN F_COMPTET ON F_CREGLEMENT.CT_NumPayeurOrig = F_COMPTET.CT_Num INNER JOIN F_JOURNAUX ON F_CREGLEMENT.JO_Num = F_JOURNAUX.JO_Num LEFT OUTER JOIN P_REGLEMENT ON F_CREGLEMENT.N_Reglement = P_REGLEMENT.cbIndice LEFT OUTER JOIN P_DEVISE ON F_CREGLEMENT.N_Devise = P_DEVISE.cbIndice WHERE (F_CREGLEMENT.RG_Type = 1)',
N'Paiements_Fournisseurs', N'N° interne', N'DB', 'incremental', N'Date modification', 'normal', 16, 1);

-- 15. Imputation factures achats (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Imputation factures des achats',
N'SELECT F_CREGLEMENT.RG_Reference AS Référence, F_CREGLEMENT.RG_Libelle AS Libellé, F_REGLECH.RG_No [id Réglement], F_CREGLEMENT.RG_Date AS [Date réglement], F_CREGLEMENT.RG_DateEchCont AS [Date d''échance], F_REGLECH.DR_No AS [Id écheance], ISNULL( CASE WHEN F_REGLECH.DO_Domaine = 1 THEN CASE F_DOCENTETE.DO_Type WHEN 10 THEN ''Demande d''''achat'' WHEN 11 THEN ''Bon de commande'' WHEN 12 THEN ''Préparation de livraison'' WHEN 13 THEN ''Bon de livraison'' WHEN 14 THEN ''Bon de retour'' WHEN 15 THEN ''Bon avoir financier'' WHEN 16 THEN CASE DO_Provenance WHEN 0 THEN ''Facture'' WHEN 1 THEN ''Facture de retour'' WHEN 2 THEN ''Facture avoir'' WHEN 3 THEN ''Facture caisse décentralisée'' WHEN 4 THEN ''Facture d"accompte'' END WHEN 17 THEN CASE DO_Provenance WHEN 0 THEN ''Facture comptabilisée'' WHEN 1 THEN ''Facture de retour comptabilisée'' WHEN 2 THEN ''Facture avoir comptabilisée'' WHEN 3 THEN ''Facture caisse décentralisée comptabilisée'' WHEN 4 THEN ''Facture d"accompte comptabilisée'' END WHEN 18 THEN ''Archive'' ELSE ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'' END ELSE CASE F_DOCENTETE.DO_Type WHEN 0 THEN ''Devis'' WHEN 1 THEN ''Bon de commande'' WHEN 2 THEN ''Préparation de livraison'' WHEN 3 THEN ''Bon de livraison'' WHEN 4 THEN ''Bon de retour'' WHEN 5 THEN ''Bon avoir financier'' WHEN 6 THEN CASE DO_Provenance WHEN 0 THEN ''Facture'' WHEN 1 THEN ''Facture de retour'' WHEN 2 THEN ''Facture avoir'' WHEN 3 THEN ''Facture caisse décentralisée'' END WHEN 7 THEN CASE DO_Provenance WHEN 0 THEN ''Facture comptabilisée'' WHEN 1 THEN ''Facture de retour comptabilisée'' WHEN 2 THEN ''Facture avoir comptabilisée'' WHEN 3 THEN ''Facture caisse décentralisée comptabilisée'' END WHEN 8 THEN ''Archive'' ELSE ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'' END END, ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'' ) AS [Type Document], F_REGLECH.DO_Piece AS [N° pièce], (SELECT SUM(DL_MontantTTC) AS Expr1 FROM F_DOCLIGNE AS ligne WHERE (DO_Type = F_REGLECH.DO_Type) AND (DO_Piece = F_REGLECH.DO_Piece)) AS [Montant facture TTC], F_REGLECH.RC_Montant AS [Montant régler], F_DOCENTETE.DO_Date AS [Date document], P_REGLEMENT.R_Intitule AS [Mode de réglement], F_DOCENTETE.DO_Tiers AS [Code fournisseur], F_COMPTET_1.CT_Intitule AS [Intitulé fournisseur], F_COMPTET.CT_Num [Code tier encaisseur], F_COMPTET.CT_Intitule [Intitulé tier encaisseur] ,RG_Montant [Montant réglement] , F_REGLECH.cbCreation [Date création], F_REGLECH.cbModification [Date modification] FROM F_REGLECH INNER JOIN F_DOCENTETE ON F_REGLECH.DO_Type = F_DOCENTETE.DO_Type AND F_REGLECH.DO_Piece = F_DOCENTETE.DO_Piece INNER JOIN F_COMPTET AS F_COMPTET_1 ON F_DOCENTETE.DO_Tiers = F_COMPTET_1.CT_Num INNER JOIN F_COMPTET ON F_DOCENTETE.CT_NumPayeur = F_COMPTET.CT_Num INNER JOIN F_CREGLEMENT ON F_REGLECH.RG_No = F_CREGLEMENT.RG_No INNER JOIN P_REGLEMENT ON F_CREGLEMENT.N_Reglement = P_REGLEMENT.cbIndice WHERE (F_DOCENTETE.DO_Domaine =1)',
N'Imputation_Factures_Achats', NULL, N'DB', 'incremental', N'Date modification', 'normal', 17, 0);

-- 16. Lignes des achats (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Lignes des achats',
N'SELECT DL_No [N° interne], ISNULL(CASE F_DOCENTETE.DO_Type WHEN 10 THEN ''Demande d''''achat'' WHEN 11 THEN ''Préparation de commande'' WHEN 12 THEN ''Bon de commande'' WHEN 13 THEN ''Bon de livraison'' WHEN 14 THEN ''Bon de retour'' WHEN 15 THEN ''Bon avoir financier'' WHEN 16 THEN CASE DO_Provenance WHEN 0 THEN ''Facture'' WHEN 1 THEN ''Facture de retour'' WHEN 2 THEN ''Facture avoir'' WHEN 3 THEN ''Facture caisse décentralisée'' END WHEN 17 THEN CASE DO_Provenance WHEN 0 THEN ''Facture comptabilisée'' WHEN 1 THEN ''Facture de retour comptabilisée'' WHEN 2 THEN ''Facture avoir comptabilisée'' WHEN 3 THEN ''Facture caisse décentralisée comptabilisée'' END WHEN 18 THEN ''Archive'' ELSE ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'' END, '''') AS [Type Document], CASE WHEN F_DOCLIGNE.DO_Type < 13 THEN ''Non'' ELSE ''Oui'' END AS [Valorise CA], F_DOCENTETE.DO_Tiers AS [Code fournisseur], F_COMPTET.CT_Intitule AS [Intitulé fournisseur], ISNULL(F_DOCLIGNE.DO_Piece, '''') AS [N° Pièce], F_DOCLIGNE.DO_Ref AS Référence, ( SELECT TOP 1 CA_Intitule FROM F_COMPTEA WHERE F_COMPTEA.CA_Num = F_DOCLIGNE.CA_Num) AS [Intitulé affaire], F_DOCLIGNE.CA_Num AS [Code d''affaire], CONVERT(DATETIME, F_DOCENTETE.DO_Date, 3) AS [Date], CASE WHEN F_DOCLIGNE.DO_Type = 3 THEN F_DOCLIGNE.DO_Piece WHEN F_DOCLIGNE.DO_Type > 3 THEN F_DOCLIGNE.DL_PieceBL END AS [N° Pièce BL], CASE WHEN F_DOCLIGNE.DO_Type = 3 THEN F_DOCLIGNE.DO_Date WHEN F_DOCLIGNE.DO_Type > 3 THEN CASE WHEN F_DOCLIGNE.DL_DateBL < 0 THEN ''01/01/1900'' ELSE F_DOCLIGNE.DL_DateBL END END AS [Date BL], CASE F_DOCLIGNE.DO_Type WHEN 1 THEN F_DOCLIGNE.DO_Piece ELSE F_DOCLIGNE.DL_PieceBC END AS [N° Pièce BC], CASE F_DOCLIGNE.DO_Type WHEN 1 THEN F_DOCLIGNE.DO_Date ELSE CASE WHEN F_DOCLIGNE.DL_DateBC < 0 THEN ''01/01/1900'' ELSE F_DOCLIGNE.DL_DateBC END END AS [Date BC], F_DOCLIGNE.DL_PiecePL AS [N° pièce PL], F_DOCLIGNE.DL_DatePL AS [Date PL], CASE WHEN F_DOCLIGNE.DO_DateLivr < 0 THEN NULL ELSE F_DOCLIGNE.DO_DateLivr END AS [Date Livraison], F_DOCLIGNE.AR_Ref AS [Code article], F_DOCLIGNE.DL_Design AS Désignation, F_CATALOGUE_1.CL_Intitule AS [Catalogue 1], F_CATALOGUE.CL_Intitule AS [Catalogue 2], F_CATALOGUE_2.CL_Intitule AS [Catalogue 3], F_CATALOGUE_3.CL_Intitule AS [Catalogue 4], P_GAMME.G_Intitule AS [Gamme 1], P_GAMME_1.G_Intitule AS [Gamme 2], CASE F_DOCENTETE.DO_Colisage WHEN 0 THEN P_UNITE.U_Intitule ELSE CAST(F_DOCENTETE.DO_Colisage AS VARCHAR) + '' '' + P_UNITE.U_Intitule END AS Colisage, CAST(F_DOCLIGNE.DL_PoidsBrut / ( SELECT CASE PR_UnitePoids WHEN 0 THEN 1000000.000 WHEN 1 THEN 100000.000 WHEN 2 THEN 1000.000 WHEN 3 THEN 1.000 WHEN 4 THEN 0.001 END AS Expr1 FROM P_PREFERENCES) AS FLOAT) AS [Poids brut], CAST(F_DOCLIGNE.DL_PoidsNet / ( SELECT CASE PR_UnitePoids WHEN 0 THEN 1000000.000 WHEN 1 THEN 100000.000 WHEN 2 THEN 1000.000 WHEN 3 THEN 1.000 WHEN 4 THEN 0.001 END AS Expr1 FROM P_PREFERENCES AS P_PREFERENCES_1) AS FLOAT) AS [Poids net], CASE FART.AR_SuiviStock WHEN 1 THEN CASE F_DOCLIGNE.DL_MvtStock WHEN 0 THEN (SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoOut) WHEN 1 THEN (SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoIn) WHEN 3 THEN (SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoOut) END WHEN 5 THEN CASE F_DOCLIGNE.DL_MvtStock WHEN 0 THEN (SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoOut) WHEN 1 THEN (SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoIn) WHEN 3 THEN (SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoOut) END END AS [N° Série/Lot], CASE DL_Taxe1 WHEN 0 THEN STR(DL_Taxe1) + ''%'' ELSE CASE DL_TypeTaux1 WHEN 0 THEN STR(DL_Taxe1, 6, 2) + ''%'' WHEN 1 THEN STR(DL_Taxe1, 6, 2) + ''F'' WHEN 2 THEN STR(DL_Taxe1, 6, 2) + ''U'' ELSE ''ERREUR. Contacter votre revendeur.'' END END AS Taxe1, CASE DL_Taxe2 WHEN 0 THEN STR(DL_Taxe2) + ''%'' ELSE CASE DL_TypeTaux2 WHEN 0 THEN STR(DL_Taxe2, 6, 2) + ''%'' WHEN 1 THEN STR(DL_Taxe2, 6, 2) + ''F'' WHEN 2 THEN STR(DL_Taxe2, 6, 2) + ''U'' ELSE ''ERREUR. Contacter votre revendeur.'' END END AS Taxe2, CASE DL_Taxe3 WHEN 0 THEN STR(DL_Taxe3) + ''%'' ELSE CASE DL_TypeTaux3 WHEN 0 THEN STR(DL_Taxe3, 6, 2) + ''%'' WHEN 1 THEN STR(DL_Taxe3, 6, 2) + ''F'' WHEN 2 THEN STR(DL_Taxe3, 6, 2) + ''U'' ELSE ''ERREUR. Contacter votre revendeur.'' END END AS Taxe3, CASE DL_TypeTaux1 WHEN 0 THEN ''Taux %'' WHEN 1 THEN ''Montant forfait'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taux taxe 1], CASE DL_TypeTaux2 WHEN 0 THEN ''Taux %'' WHEN 1 THEN ''Montant forfait'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taux taxe 2], CASE DL_TypeTaux3 WHEN 0 THEN ''Taux %'' WHEN 1 THEN ''Montant forfait'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taux taxe 3], CASE DL_TypeTaxe1 WHEN 0 THEN ''TVA/débit'' WHEN 1 THEN ''TVA/Encaissement'' WHEN 2 THEN ''TP/HT'' WHEN 3 THEN ''TP/TTC'' WHEN 4 THEN ''TP/Poids'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taxe 1], CASE DL_TypeTaxe2 WHEN 0 THEN ''TVA/débit'' WHEN 1 THEN ''TVA/Encaissement'' WHEN 2 THEN ''TP/HT'' WHEN 3 THEN ''TP/TTC'' WHEN 4 THEN ''TP/Poids'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taxe 2], CASE DL_TypeTaxe3 WHEN 0 THEN ''TVA/débit'' WHEN 1 THEN ''TVA/Encaissement'' WHEN 2 THEN ''TP/HT'' WHEN 3 THEN ''TP/TTC'' WHEN 4 THEN ''TP/Poids'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taxe 3], -- CAST(CAST(ROUND(F_DOCLIGNE.DL_Remise01REM_Valeur, 2) AS DECIMAL(18, 2)) AS varchar(100)) + ''%'' FORMAT(F_DOCLIGNE.DL_Remise01REM_Valeur, ''P2'') AS [Remise 1], FORMAT(F_DOCLIGNE.DL_Remise02REM_Valeur, ''P2'') AS [Remise 2], CAST(F_DOCLIGNE.DL_Frais AS FLOAT) AS [Frais d''approche], F_DOCLIGNE.DL_PUDevise AS [PU Devise], CASE DL_TNomencl WHEN 0 THEN ''Oui'' WHEN 1 THEN ''Non'' ELSE '' ERREUR - Contactez votre revendeur.'' END AS Nomenclature, CASE DL_TRemPied WHEN 0 THEN ''Oui'' WHEN 1 THEN ''Non'' ELSE '' ERREUR - Contactez votre revendeur.'' END AS [Type remise de pied], CASE DL_TRemExep WHEN 0 THEN ''Oui'' WHEN 1 THEN ''Non'' ELSE '' ERREUR - Contactez votre revendeur.'' END AS [Type remise exceptionnelle], F_DOCLIGNE.DL_CMUP AS CMUP, F_DOCLIGNE.DL_PrixUnitaire AS [Prix unitaire], F_DOCLIGNE.DL_PUTTC AS [Prix unitaire TTC], CASE WHEN F_DOCLIGNE.DO_Type <> 5 AND F_DOCLIGNE.DO_Type <> 15 AND DL_TRemPied = 0 AND DL_TRemExep = 0 AND DL_TypePL < 2 AND AR_FactForfait = 0 THEN CASE WHEN (F_DOCLIGNE.DO_Domaine = 4) THEN 0 ELSE CASE WHEN ( F_DOCLIGNE.DO_Type = 4 OR F_DOCLIGNE.DO_Type = 14) THEN -DL_Qte ELSE DL_Qte END END ELSE 0 END AS [Quantité], F_DOCLIGNE.DL_QtePL AS [Quantité PL], F_DOCLIGNE.DL_QteRessource AS [Qté Ressource], CASE WHEN ( ( F_DOCLIGNE.DO_Type >= 4 AND F_DOCLIGNE.DO_Type <= 5) OR ( F_DOCLIGNE.DO_Type >= 14 AND F_DOCLIGNE.DO_Type <= 15)) THEN -DL_MontantHT ELSE DL_MontantHT END AS [Montant HT Net], CASE WHEN ( ( F_DOCLIGNE.DO_Type >= 4 AND F_DOCLIGNE.DO_Type <= 5) OR ( F_DOCLIGNE.DO_Type >= 14 AND F_DOCLIGNE.DO_Type <= 15)) THEN -DL_MontantTTC ELSE DL_MontantTTC END AS [Montant TTC Net], DL_PrixRU [Prix de revient], F_DOCLIGNE.DE_No [Code dépôt], DE_Intitule [Intitulé dépôt], DL_PUBC [Prix unitaire BC], EU_Enumere Conditionnement, CASE [DL_Remise01REM_Type] WHEN 0 THEN ''Montant'' WHEN 1 THEN ''Pourcentage'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type de la remise 1], CASE [DL_Remise02REM_Type] WHEN 0 THEN ''Montant'' WHEN 1 THEN ''Pourcentage'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type de la remise 2], AF_RefFourniss [Référence article fournisseur], DL_FactPoids [Article facturé au poids], F_DOCLIGNE.cbCreation [Date création], F_DOCLIGNE.cbModification [Date modification] FROM F_DOCLIGNE INNER JOIN F_ARTICLE AS FART ON F_DOCLIGNE.cbAR_Ref = FART.cbAR_Ref INNER JOIN F_DOCENTETE ON F_DOCLIGNE.DO_Type = F_DOCENTETE.DO_Type AND F_DOCLIGNE.DO_Piece = F_DOCENTETE.DO_Piece INNER JOIN F_COMPTET ON F_DOCENTETE.cbDO_Tiers = F_COMPTET.cbCT_Num INNER JOIN F_FAMILLE ON FART.FA_CodeFamille = F_FAMILLE.FA_CodeFamille INNER JOIN F_COMPTET AS F_COMPTET_1 ON F_COMPTET.CT_NumPayeur = F_COMPTET_1.CT_Num LEFT OUTER JOIN P_GAMME AS P_GAMME_1 ON F_DOCLIGNE.AG_No2 = P_GAMME_1.cbIndice LEFT OUTER JOIN P_GAMME ON F_DOCLIGNE.AG_No1 = P_GAMME.cbIndice LEFT OUTER JOIN F_DEPOT ON F_DOCLIGNE.DE_No = F_DEPOT.DE_No LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_3 ON FART.CL_No4 = F_CATALOGUE_3.CL_No LEFT OUTER JOIN F_CATALOGUE ON FART.CL_No2 = F_CATALOGUE.CL_No LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_2 ON FART.CL_No3 = F_CATALOGUE_2.CL_No LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_1 ON FART.CL_No1 = F_CATALOGUE_1.CL_No LEFT OUTER JOIN P_DEVISE ON F_DOCENTETE.DO_Devise = P_DEVISE.cbIndice LEFT OUTER JOIN P_UNITE ON F_DOCENTETE.DO_TypeColis = P_UNITE.cbIndice WHERE (F_DOCLIGNE.DO_Domaine = 1) AND (F_DOCLIGNE.DL_TRemExep < 2) AND (F_DOCLIGNE.DL_NonLivre = 0)',
N'Lignes_des_achats', N'N° interne', N'DB', 'incremental', N'Date modification', 'normal', 18, 0);

-- 17. Echeances achats (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Echéances achats',
N'select [Code tier payeur], [Type Document],[Date d''échéance],[Pourcentage],[N° pièce],[Montant échéance devise],Régler, [Montant TTC], [Mode de réglement],[Tier payeur],[Intitulé fournisseur],[Code fournisseur],[Date document], case when countt = 1 then [Montant TTC] else case when [Montant échance1]<>0 then [Montant échance1] else [Montant TTC]-sum([Montant échance1])over(partition by [N° pièce] order by DR_Equil) end end [Montant échéance] ,[N° interne],[Date création],[Date modification] from ( SELECT DR_Equil , F_DOCENTETE.CT_NumPayeur AS [Code tier payeur], ISNULL( CASE WHEN F_DOCENTETE.DO_Domaine = 1 THEN CASE F_DOCENTETE.DO_Type WHEN 10 THEN ''Demande d''''achat'' WHEN 11 THEN ''Bon de commande'' WHEN 12 THEN ''Préparation de livraison'' WHEN 13 THEN ''Bon de livraison'' WHEN 14 THEN ''Bon de retour'' WHEN 15 THEN ''Bon avoir financier'' WHEN 16 THEN CASE DO_Provenance WHEN 0 THEN ''Facture'' WHEN 1 THEN ''Facture de retour'' WHEN 2 THEN ''Facture avoir'' WHEN 3 THEN ''Facture caisse décentralisée'' WHEN 4 THEN ''Facture d"accompte'' END WHEN 17 THEN CASE DO_Provenance WHEN 0 THEN ''Facture comptabilisée'' WHEN 1 THEN ''Facture de retour comptabilisée'' WHEN 2 THEN ''Facture avoir comptabilisée'' WHEN 3 THEN ''Facture caisse décentralisée comptabilisée'' WHEN 4 THEN ''Facture d"accompte comptabilisée'' END WHEN 18 THEN ''Archive'' ELSE ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'' END ELSE CASE F_DOCENTETE.DO_Type WHEN 0 THEN ''Devis'' WHEN 1 THEN ''Bon de commande'' WHEN 2 THEN ''Préparation de livraison'' WHEN 3 THEN ''Bon de livraison'' WHEN 4 THEN ''Bon de retour'' WHEN 5 THEN ''Bon avoir financier'' WHEN 6 THEN CASE DO_Provenance WHEN 0 THEN ''Facture'' WHEN 1 THEN ''Facture de retour'' WHEN 2 THEN ''Facture avoir'' WHEN 3 THEN ''Facture caisse décentralisée'' END WHEN 7 THEN CASE DO_Provenance WHEN 0 THEN ''Facture comptabilisée'' WHEN 1 THEN ''Facture de retour comptabilisée'' WHEN 2 THEN ''Facture avoir comptabilisée'' WHEN 3 THEN ''Facture caisse décentralisée comptabilisée'' END WHEN 8 THEN ''Archive'' ELSE ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'' END END, ''ERREUR sur F_DOCENTETE.DO_Type - Contactez votre revendeur.'' ) AS [Type Document], F_DOCREGL.DO_Piece AS [N° pièce], F_DOCREGL.DR_Date AS [Date d''échéance], F_DOCREGL.DR_Pourcent [Pourcentage], ISNULL(CASE WHEN F_DOCREGL.DR_Equil = 0 THEN (CASE when DR_Pourcent=0 then F_DOCREGL.DR_Montant else SUM( DL_MontantTTC)*DR_Pourcent/100 end ) end ,0) AS [Montant échance1], F_DOCREGL.DR_MontantDev AS [Montant échéance devise], CASE WHEN F_DOCREGL.DR_Regle = 0 THEN ''Non'' ELSE ''Oui'' END AS Régler, SUM(F_DOCLIGNE.DL_MontantTTC) AS [Montant TTC], P_REGLEMENT.R_Intitule AS [Mode de réglement], F_COMPTET.CT_Intitule [Tier payeur], F_COMPTET_1.CT_Intitule AS [Intitulé fournisseur], F_DOCENTETE.DO_Tiers [Code fournisseur] ,F_DOCENTETE.DO_Date [Date document] , count(F_DOCREGL.DO_Piece)over(partition by F_DOCLIGNE.DO_Piece,F_DOCLIGNE.DO_Type)countt ,dr_no [N° interne], F_DOCREGL.cbCreation [Date création], F_DOCREGL.cbModification [Date modification] FROM F_DOCENTETE INNER JOIN F_DOCLIGNE ON F_DOCENTETE.DO_Type = F_DOCLIGNE.DO_Type AND F_DOCENTETE.DO_Piece = F_DOCLIGNE.DO_Piece INNER JOIN F_COMPTET ON F_DOCENTETE.CT_NumPayeur = F_COMPTET.CT_Num INNER JOIN F_COMPTET AS F_COMPTET_1 ON F_DOCENTETE.DO_Tiers = F_COMPTET_1.CT_num LEFT OUTER JOIN F_DOCREGL INNER JOIN P_REGLEMENT ON F_DOCREGL.N_Reglement = P_REGLEMENT.cbIndice ON F_DOCLIGNE.DO_Piece = F_DOCREGL.DO_Piece AND F_DOCLIGNE.DO_Type = F_DOCREGL.DO_Type WHERE isnull(F_DOCREGL.DO_Domaine,99)=1 and (F_DOCLIGNE.DO_Type IN (16, 17 )) GROUP BY F_DOCENTETE.DO_Tiers,F_DOCENTETE.DO_Provenance, F_DOCLIGNE.DO_Piece, F_DOCENTETE.DO_Type, F_DOCLIGNE.DO_Type, F_DOCREGL.DR_No, F_DOCENTETE.DO_Domaine, F_DOCREGL.DO_Type, F_DOCREGL.DO_Piece, F_DOCREGL.DR_Date, F_DOCREGL.DR_Libelle, F_DOCREGL.DR_Pourcent, F_DOCREGL.DR_Montant, F_DOCREGL.DR_MontantDev, F_DOCREGL.DR_Equil, F_DOCREGL.DR_Regle, F_DOCREGL.N_Reglement, P_REGLEMENT.R_Intitule, F_COMPTET.CT_Intitule, F_DOCENTETE.CT_NumPayeur, F_COMPTET_1.CT_Intitule, F_DOCENTETE.DO_Tiers ,F_DOCENTETE.DO_Date ,F_DOCREGL.cbCreation , F_DOCREGL.cbModification ) tab',
N'Echeances_Achats', N'N° interne', N'DB', 'incremental', N'Date modification', 'normal', 19, 0);

