-- PRIORITE NORMAL - DOCUMENTS INTERNES (2 tables)
-- ─────────────────────────────────────────────────────────────────

-- 18. Entete documents internes (FULL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Entête des documents interne',
N'SELECT CASE WHEN F_DOCENTETE.DO_TYPE BETWEEN 0 AND 6 THEN ''OUI'' ELSE ''NON'' END AS Encours, ISNULL( (SELECT D_Intitule FROM dbo.P_INTERNE WHERE 39+cbIndice =DO_Type),''Erreur. Contactez votre revendeur.'' ) AS [Type Document], ( SELECT S_Intitule FROM dbo.P_SOUCHEINTERNE WHERE cbIndice = DO_Souche+1 ) Souche, CASE DO_STATUT WHEN 0 THEN ''Saisi'' WHEN 1 THEN ''Confermé'' WHEN 2 THEN ''Accepté'' END AS Statut, F_DOCENTETE.DO_Tiers AS [Code client], F_COMPTET.CT_Intitule AS [Intitulé client], F_DOCENTETE.CO_No [Code représentant] ,COLLABORATEUR_DOC.co_nom [Nom représentant] , CONVERT(DATETIME, F_DOCENTETE.DO_Date, 3) AS [Date], isnull( F_DOCENTETE.DO_Piece ,'''') AS [N° pièce], CASE WHEN F_DOCENTETE.DO_Ventile = 0 THEN ''Non'' ELSE ''Oui'' END AS [Document ventilé], CASE WHEN F_DOCENTETE.DO_RELIQUAT = 1 THEN ''Reliquat'' WHEN F_DOCENTETE.DO_RELIQUAT = 0 AND F_DOCENTETE.DO_IMPRIM = 1 THEN ''Imprimé'' WHEN F_DOCENTETE.DO_RELIQUAT = 0 AND F_DOCENTETE.DO_IMPRIM = 0 THEN '' '' ELSE ''ERREUR. Contactez votre revendeur.'' END AS Etat,F_DOCENTETE.DO_Coord01 AS [Entête 1], F_DOCENTETE.DO_Coord02 AS [Entête 2], F_DOCENTETE.DO_Coord03 AS [Entête 3], F_DOCENTETE.DO_Coord04 AS [Entête 4], F_DOCENTETE.CT_NumPayeur AS [N° Compte Payeur], F_COMPTET_1.CT_Intitule AS [Intitulé tiers payeur], F_DEPOT.DE_Intitule AS Dépôt, ISNULL(P_DEVISE.D_Intitule, ''Aucune'') AS Devise, P_EXPEDITION.E_Intitule AS Expédition, CASE (F_DOCENTETE.DO_LANGUE) WHEN 0 THEN ''Aucune'' WHEN 1 THEN ''Langue 1'' WHEN 2 THEN ''Langue 2'' END AS Langue, CASE F_DOCENTETE.DO_BLFACT WHEN 1 THEN ''OUI'' WHEN 0 THEN ''NON'' END AS [Fact/BL], F_DOCENTETE.DO_NbFacture AS [Nb Facture], F_DOCENTETE.CG_Num AS [Compte Général], F_DOCENTETE.CA_Num [Code d''affaire], ( SELECT TOP 1 CA_Intitule FROM F_COMPTEA WHERE F_COMPTEA.CA_Num = F_DOCENTETE.ca_num) AS [Intitulé affaire], case F_DOCENTETE.N_CATCOMPTA WHEN 1 THEN (SELECT P_CATCOMPTA.CA_COMPTAVEN01 FROM P_CATCOMPTA) WHEN 2 THEN (SELECT P_CATCOMPTA.CA_COMPTAVEN02 FROM P_CATCOMPTA) WHEN 3 THEN (SELECT P_CATCOMPTA.CA_COMPTAVEN03 FROM P_CATCOMPTA) WHEN 4 THEN (SELECT P_CATCOMPTA.CA_COMPTAVEN04 FROM P_CATCOMPTA) WHEN 5 THEN (SELECT P_CATCOMPTA.CA_COMPTAVEN05 FROM P_CATCOMPTA) WHEN 6 THEN (SELECT P_CATCOMPTA.CA_COMPTAVEN06 FROM P_CATCOMPTA) WHEN 7 THEN (SELECT P_CATCOMPTA.CA_COMPTAVEN07 FROM P_CATCOMPTA) WHEN 8 THEN (SELECT P_CATCOMPTA.CA_COMPTAVEN08 FROM P_CATCOMPTA) WHEN 9 THEN (SELECT P_CATCOMPTA.CA_COMPTAVEN09 FROM P_CATCOMPTA) WHEN 10 THEN (SELECT P_CATCOMPTA.CA_COMPTAVEN10 FROM P_CATCOMPTA) ELSE '' '' END AS [Catégorie Comptable], F_DEPOT.DE_No AS [Code dépôt], F_DOCENTETE.DO_Ref AS Référence, F_DOCENTETE.DO_Cours AS Cours, F_DOCENTETE.DO_TxEscompte AS [Taux escompte], CASE WHEN DO_Reliquat = 0 THEN ''Reliquet'' ELSE ''Non'' END AS [Document de reliquat], CASE WHEN DO_Imprim = 0 THEN ''Oui'' ELSE ''Non'' END AS [Document imprimé ], F_DOCENTETE.DO_DateLivr AS [Date livraison souhite], F_DOCENTETE.DO_DebutAbo AS [Date début de l’abonnement lié], F_DOCENTETE.DO_FinAbo AS [Date fin de l’abonnement lié], F_DOCENTETE.DO_DebutPeriod AS [Date début de la périodicité liée], F_DOCENTETE.DO_FinPeriod AS [Date Fin de la périodicité liée], F_DOCENTETE.DO_Cloture AS [Document clôturé] , CASE DO_TypeFrais WHEN 0 THEN ''Montant Forfaitaire'' WHEN 1 THEN ''Quantité'' WHEN 2 THEN ''Poids net'' WHEN 3 THEN ''Poids brut'' ELSE ''Erreur. Contactez votre revendeur.'' END AS [Type frais], F_DOCENTETE.DO_ValFrais AS [Valeur frais], CASE WHEN DO_TypeLigneFrais = 0 THEN ''HT'' ELSE ''TTC'' END AS [Type HT/TTC frais], CASE WHEN DO_Valide = 0 THEN ''Oui'' ELSE ''Non'' END AS [Statut validé], P_DEVISE.D_Intitule AS [Intitulé dépôt], P_CATTARIF.CT_Intitule AS [Catégorie tarifaire ], P_CONDLIVR.C_Intitule AS [Condition de livraison], CASE F_DOCENTETE.DO_COLISAGE WHEN 0 THEN P_UNITE.U_INTITULE ELSE CAST(F_DOCENTETE.DO_COLISAGE AS VARCHAR) + '' '' + P_UNITE.U_INTITULE END AS Colisage, F_DOCENTETE.DO_TotalHT AS [Montant HT], F_DOCENTETE.DO_TotalTTC [Montant TTC], F_DOCENTETE.DO_NetAPayer [Montant net à payer], F_DOCENTETE.DO_MontantRegle [Montant réglé], F_LIVRAISON.LI_No AS [Code lieu de livraison], F_LIVRAISON.LI_Intitule [Lieu de livraison] ,F_DOCENTETE.cbModification [Date modification] FROM P_CATTARIF RIGHT OUTER JOIN F_COMPTET AS F_COMPTET_1 INNER JOIN F_COMPTET INNER JOIN F_DOCENTETE ON F_COMPTET.cbCT_Num = F_DOCENTETE.cbDO_Tiers ON F_COMPTET_1.CT_Num = F_COMPTET.CT_NumPayeur INNER JOIN F_DEPOT ON F_DOCENTETE.DE_No = F_DEPOT.DE_No LEFT OUTER JOIN F_LIVRAISON ON F_DOCENTETE.cbLI_No = F_LIVRAISON.LI_No LEFT OUTER JOIN P_CONDLIVR ON F_DOCENTETE.DO_DateLivr = P_CONDLIVR.cbIndice ON P_CATTARIF.cbIndice = F_DOCENTETE.DO_Tarif LEFT OUTER JOIN F_COLLABORATEUR AS COLLABORATEUR_DOC ON F_DOCENTETE.cbCO_No = COLLABORATEUR_DOC.CO_No LEFT OUTER JOIN P_DEVISE ON F_DOCENTETE.DO_Devise = P_DEVISE.cbIndice LEFT OUTER JOIN P_EXPEDITION ON F_DOCENTETE.DO_Expedit = P_EXPEDITION.cbIndice LEFT OUTER JOIN P_UNITE ON F_DOCENTETE.DO_TypeColis = P_UNITE.cbIndice WHERE (F_DOCENTETE.DO_Domaine IN (4))',
N'Entête_des_documents_internes', N'N° pièce', N'DB', 'incremental', N'Date modification', 'normal', 21, 1);

-- 19. Lignes documents internes (FULL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Ligne des documents internes',
N'SELECT DL_No [N° interne], ISNULL( (SELECT D_Intitule FROM dbo.P_INTERNE WHERE 39+cbIndice = F_DOCLIGNE.DO_Type),''Erreur. Contactez votre revendeur.'' ) AS [Type Document], F_DOCENTETE.DO_Tiers AS [Code client], F_COMPTET.CT_Intitule AS [Intitulé client], ISNULL(F_DOCLIGNE.DO_Piece, '''') AS [N° Pièce], F_DOCLIGNE.DO_Ref AS Référence, F_COMPTEA.CA_Intitule AS [Intitule affaire], F_COMPTEA.CA_Num AS [Code affaire], CONVERT(DATETIME, F_DOCENTETE.DO_Date, 3) AS [Date], CONVERT(DATETIME, F_DOCENTETE.DO_Date, 3) AS [Date document], CASE WHEN F_DOCLIGNE.DO_DateLivr < 0 THEN NULL ELSE F_DOCLIGNE.DO_DateLivr END AS [Date Livraison], F_DOCLIGNE.AR_Ref AS [Code article], F_DOCLIGNE.DL_Design AS Désignation, F_CATALOGUE_1.CL_Intitule AS [Catalogue 1], F_CATALOGUE.CL_Intitule AS [Catalogue 2], F_CATALOGUE_2.CL_Intitule AS [Catalogue 3], F_CATALOGUE_3.CL_Intitule AS [Catalogue 4], P_GAMME.G_Intitule AS [Gamme 1], P_GAMME_1.G_Intitule AS [Gamme 2], CASE F_DOCENTETE.DO_Colisage WHEN 0 THEN P_UNITE.U_Intitule ELSE CAST(F_DOCENTETE.DO_Colisage AS VARCHAR) + '' '' + P_UNITE.U_Intitule END AS Colisage, CAST(F_DOCLIGNE.DL_PoidsBrut / ( SELECT CASE PR_UnitePoids WHEN 0 THEN 1000000.000 WHEN 1 THEN 100000.000 WHEN 2 THEN 1000.000 WHEN 3 THEN 1.000 WHEN 4 THEN 0.001 END AS Expr1 FROM P_PREFERENCES ) AS FLOAT) AS [Poids brut], CAST(F_DOCLIGNE.DL_PoidsNet / ( SELECT CASE PR_UnitePoids WHEN 0 THEN 1000000.000 WHEN 1 THEN 100000.000 WHEN 2 THEN 1000.000 WHEN 3 THEN 1.000 WHEN 4 THEN 0.001 END AS Expr1 FROM P_PREFERENCES AS P_PREFERENCES_1 ) AS FLOAT) AS [Poids net], CASE FART.AR_SuiviStock WHEN 1 THEN CASE F_DOCLIGNE.DL_MvtStock WHEN 0 THEN ( SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoOut ) WHEN 1 THEN ( SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoIn ) WHEN 3 THEN ( SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoOut ) END WHEN 5 THEN CASE F_DOCLIGNE.DL_MvtStock WHEN 0 THEN ( SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoOut ) WHEN 1 THEN ( SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoIn ) WHEN 3 THEN ( SELECT TOP 1 LS_NoSerie FROM F_LOTSERIE WHERE DL_No = DL_NoOut ) END END AS [N° Série/Lot], CASE DL_Taxe1 WHEN 0 THEN STR(DL_Taxe1) + ''%'' ELSE CASE DL_TypeTaux1 WHEN 0 THEN STR(DL_Taxe1, 6, 2) + ''%'' WHEN 1 THEN STR(DL_Taxe1, 6, 2) + ''F'' WHEN 2 THEN STR(DL_Taxe1, 6, 2) + ''U'' ELSE ''ERREUR. Contacter votre revendeur.'' END END AS Taxe1, CASE DL_Taxe2 WHEN 0 THEN STR(DL_Taxe2) + ''%'' ELSE CASE DL_TypeTaux2 WHEN 0 THEN STR(DL_Taxe2, 6, 2) + ''%'' WHEN 1 THEN STR(DL_Taxe2, 6, 2) + ''F'' WHEN 2 THEN STR(DL_Taxe2, 6, 2) + ''U'' ELSE ''ERREUR. Contacter votre revendeur.'' END END AS Taxe2, CASE DL_Taxe3 WHEN 0 THEN STR(DL_Taxe3) + ''%'' ELSE CASE DL_TypeTaux3 WHEN 0 THEN STR(DL_Taxe3, 6, 2) + ''%'' WHEN 1 THEN STR(DL_Taxe3, 6, 2) + ''F'' WHEN 2 THEN STR(DL_Taxe3, 6, 2) + ''U'' ELSE ''ERREUR. Contacter votre revendeur.'' END END AS Taxe3, CASE DL_TypeTaux1 WHEN 0 THEN ''Taux %'' WHEN 1 THEN ''Montant forfait'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taux taxe 1], CASE DL_TypeTaux2 WHEN 0 THEN ''Taux %'' WHEN 1 THEN ''Montant forfait'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taux taxe 2], CASE DL_TypeTaux3 WHEN 0 THEN ''Taux %'' WHEN 1 THEN ''Montant forfait'' WHEN 2 THEN ''Quantité'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taux taxe 3], CASE DL_TypeTaxe1 WHEN 0 THEN ''TVA/débit'' WHEN 1 THEN ''TVA/Encaissement'' WHEN 2 THEN ''TP/HT'' WHEN 3 THEN ''TP/TTC'' WHEN 4 THEN ''TP/Poids'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taxe 1], CASE DL_TypeTaxe2 WHEN 0 THEN ''TVA/débit'' WHEN 1 THEN ''TVA/Encaissement'' WHEN 2 THEN ''TP/HT'' WHEN 3 THEN ''TP/TTC'' WHEN 4 THEN ''TP/Poids'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taxe 2], CASE DL_TypeTaxe3 WHEN 0 THEN ''TVA/débit'' WHEN 1 THEN ''TVA/Encaissement'' WHEN 2 THEN ''TP/HT'' WHEN 3 THEN ''TP/TTC'' WHEN 4 THEN ''TP/Poids'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Type taxe 3], -- CAST(CAST(ROUND(F_DOCLIGNE.DL_Remise01REM_Valeur, 2) AS DECIMAL(18, 2)) AS varchar(100)) + ''%'' FORMAT(F_DOCLIGNE.DL_Remise01REM_Valeur, ''P2'') AS [Remise 1], FORMAT(F_DOCLIGNE.DL_Remise02REM_Valeur, ''P2'') AS [Remise 2], CAST(F_DOCLIGNE.DL_Frais AS FLOAT) AS [Frais d''approche], F_DOCLIGNE.DL_PUDevise AS [PU Devise], CASE DL_TNomencl WHEN 0 THEN ''Oui'' WHEN 1 THEN ''Non'' ELSE '' ERREUR - Contactez votre revendeur.'' END AS Nomenclature, CASE DL_TRemPied WHEN 0 THEN ''Oui'' WHEN 1 THEN ''Non'' ELSE '' ERREUR - Contactez votre revendeur.'' END AS [Type remise de pied], CASE DL_TRemExep WHEN 0 THEN ''Oui'' WHEN 1 THEN ''Non'' ELSE '' ERREUR - Contactez votre revendeur.'' END AS [Type remise exceptionnelle], F_DOCLIGNE.DL_CMUP AS CMUP, F_DOCLIGNE.DL_PrixUnitaire AS [Prix unitaire], F_DOCLIGNE.DL_PUTTC AS [Prix unitaire TTC], DL_QTE AS [Quantité], dl_montantht AS [Montant HT Net], DL_MontantTTC AS [Montant TTC Net],DL_PrixRU [Prix de revient] ,F_DOCLIGNE.cbModification [Date modification] FROM F_DOCLIGNE INNER JOIN F_ARTICLE AS FART ON F_DOCLIGNE.cbAR_Ref = FART.cbAR_Ref INNER JOIN F_DOCENTETE ON F_DOCLIGNE.DO_Type = F_DOCENTETE.DO_Type AND F_DOCLIGNE.DO_Piece = F_DOCENTETE.DO_Piece INNER JOIN F_COMPTET ON F_DOCENTETE.cbDO_Tiers = F_COMPTET.cbCT_Num INNER JOIN F_FAMILLE ON FART.FA_CodeFamille = F_FAMILLE.FA_CodeFamille INNER JOIN F_COMPTET AS F_COMPTET_1 ON F_COMPTET.CT_NumPayeur = F_COMPTET_1.CT_Num LEFT OUTER JOIN P_GAMME AS P_GAMME_1 ON F_DOCLIGNE.AG_No2 = P_GAMME_1.cbIndice LEFT OUTER JOIN P_GAMME ON F_DOCLIGNE.AG_No1 = P_GAMME.cbIndice LEFT OUTER JOIN F_COMPTEA ON F_DOCLIGNE.CA_Num = F_COMPTEA.CA_Num LEFT OUTER JOIN F_DEPOT ON F_DOCLIGNE.DE_No = F_DEPOT.DE_No LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_3 ON FART.CL_No4 = F_CATALOGUE_3.CL_No LEFT OUTER JOIN F_CATALOGUE ON FART.CL_No2 = F_CATALOGUE.CL_No LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_2 ON FART.CL_No3 = F_CATALOGUE_2.CL_No LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_1 ON FART.CL_No1 = F_CATALOGUE_1.CL_No LEFT OUTER JOIN P_DEVISE ON F_DOCENTETE.DO_Devise = P_DEVISE.cbIndice LEFT OUTER JOIN P_UNITE ON F_DOCENTETE.DO_TypeColis = P_UNITE.cbIndice WHERE (F_DOCLIGNE.DO_Domaine = 4) AND ISNULL(F_COMPTEA.N_Analytique, 1) = 1',
N'Ligne_des_documents_interne', N'N° interne', N'DB', 'incremental', N'Date modification', 'normal', 22, 0);

