-- 20. Etat du stock (FULL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Etat du stock',
N'SELECT F_ARTSTOCK.AR_Ref AS [Code article], F_ARTSTOCK.DE_No AS [Code dépôt], F_ARTSTOCK.AS_QteMini AS [Quantité minimale], F_ARTSTOCK.AS_QteMaxi AS [Quantité maximale], F_ARTSTOCK.AS_MontSto AS [Valeur du stock (montant)], F_ARTSTOCK.AS_QteSto AS [Quantité en stock], F_ARTSTOCK.AS_QteRes AS [Quntitté réservée], F_ARTSTOCK.AS_QteCom AS [Quantité commandée], F_ARTSTOCK.AS_Principal AS [Dépôt principale], F_ARTSTOCK.cbMarq AS [N° intene], CASE WHEN AS_Mouvemente = 0 THEN ''Non'' ELSE ''Oui'' END AS [Stock mouvementé], FART.AR_Design AS [Désignation article], F_FAMILLE.FA_CodeFamille AS [Code famille], F_FAMILLE.FA_Intitule AS Intitule, F_DEPOT.DE_Intitule, P_UNITE.U_Intitule AS Unité FROM F_FAMILLE INNER JOIN F_ARTICLE AS FART INNER JOIN F_ARTSTOCK AS F_ARTSTOCK ON FART.cbAR_Ref = F_ARTSTOCK.cbAR_Ref INNER JOIN F_DEPOT ON F_ARTSTOCK.DE_No = F_DEPOT.DE_No ON F_FAMILLE.FA_CodeFamille = FART.FA_CodeFamille INNER JOIN P_UNITE ON FART.AR_UniteVen = P_UNITE.cbIndice',
N'Etat_Stock', N'N° intene', N'DB', 'full', NULL, 'normal', 24, 0);

-- 21. Mouvement stock (FULL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Mouvement stock',
N'SELECT case when F_DEPOT.DE_Exclure=0 then ''Non'' else ''Oui'' end as [Exclure du réapprovisionnement] , F_DEPOT.DE_Intitule AS [Dépôt],F_DEPOT.DE_No AS [Code Dépôt], F_FAMILLE.FA_CodeFamille AS [Code famille], F_FAMILLE.FA_Intitule AS [Intitulé famille], F_DOCLIGNE.AR_Ref AS [Code article], F_DOCENTETE.do_ref [Référence], CASE F_DOCLIGNE.DO_DOMAINE WHEN 0 THEN ''Vente'' WHEN 1 THEN ''Achat'' WHEN 2 THEN ''Stock'' WHEN 4 THEN ''Document interne'' END AS [Domaine mouvement], FART.AR_Design AS Désignation, ISNULL( CASE F_DOCLIGNE.DO_TYPE WHEN 0 THEN ''Devis'' WHEN 1 THEN ''Bon de commande'' WHEN 2 THEN ''Préparation de livraison'' WHEN 3 THEN ''Bon de livraison'' WHEN 4 THEN ''Bon de retour'' WHEN 5 THEN ''Bon avoir financier'' WHEN 6 THEN ''Facture'' WHEN 7 THEN ''Facture comptabilisée'' WHEN 8 THEN ''Archive'' WHEN 11 THEN ''Préparation de commande'' WHEN 12 THEN ''Bon de commande'' WHEN 13 THEN ''Bon de Réception'' WHEN 14 THEN ''Bon de retour'' WHEN 15 THEN ''Bon avoir'' WHEN 16 THEN ''Facture'' WHEN 17 THEN ''Facture comptabilisée'' WHEN 18 THEN ''Archive'' WHEN 20 THEN ''Mouvement entrée'' WHEN 21 THEN ''Mouvement sortie'' WHEN 22 THEN ''Dépréciation du stock'' WHEN 23 THEN ''Virement de dépôt à dépôt'' WHEN 24 THEN ''Préparation de fabrication'' WHEN 25 THEN ''Ordre de fabrication'' WHEN 26 THEN ''Bon de fabrication'' WHEN 27 THEN ''Archive'' WHEN 40 THEN (SELECT P_INTERNE.D_INTITULE FROM P_INTERNE WHERE P_INTERNE.CBINDICE + 39 = 40) WHEN 41 THEN (SELECT P_INTERNE.D_INTITULE FROM P_INTERNE WHERE P_INTERNE.CBINDICE + 39 = 41) WHEN 42 THEN (SELECT P_INTERNE.D_INTITULE FROM P_INTERNE WHERE P_INTERNE.CBINDICE + 39 = 42) WHEN 43 THEN (SELECT P_INTERNE.D_INTITULE FROM P_INTERNE WHERE P_INTERNE.CBINDICE + 39 = 43) WHEN 44 THEN (SELECT P_INTERNE.D_INTITULE FROM P_INTERNE WHERE P_INTERNE.CBINDICE + 39 = 44) WHEN 45 THEN (SELECT P_INTERNE.D_INTITULE FROM P_INTERNE WHERE P_INTERNE.CBINDICE + 39 = 45) WHEN 46 THEN (SELECT P_INTERNE.D_INTITULE FROM P_INTERNE WHERE P_INTERNE.CBINDICE + 39 = 46) ELSE ''ERREUR.Contactez votre revendeur.'' END ,'''' ) AS [Type Mouvement], F_DOCLIGNE.DL_DateBL AS [Date Mouvement], F_DOCLIGNE.DO_Piece AS [N° Pièce], F_DOCLIGNE.DL_CMUP AS [CMUP], F_DOCLIGNE.DL_PrixUnitaire AS [Prix unitaire], F_DOCLIGNE.DL_PrixRU AS [Prix de revient], cast(0 as float) [DPA-Période], FART.AR_CoutStd [Coût standard], cast(0 as float) [DPA-Vente], cast(0 as float) [DPR-Vente], CASE DL_MVTSTOCK WHEN 1 THEN CASE WHEN f_docligne.DO_TYPE = 27 OR f_docligne.DO_TYPE = 4 THEN DL_QTE ELSE CASE WHEN DL_TYPEPL > 0 OR (DL_QTE < 0 AND f_docligne.DO_DOMAINE <> 2) THEN -DL_QTE ELSE DL_QTE END END WHEN 3 THEN CASE WHEN f_docligne.DO_TYPE = 14 THEN -DL_QTE ELSE CASE WHEN DL_TYPEPL > 0 OR DL_QTE < 0 THEN DL_QTE ELSE -DL_QTE END END ELSE 0 END AS [Quantité], (SELECT DISTINCT CASE AR_SUIVISTOCK WHEN 1 THEN CASE DL_MvtStock WHEN 0 THEN (SELECT top 1 LS_NOSERIE FROM F_LOTSERIE WHERE DL_NOOUT = DL_No) WHEN 1 THEN (SELECT top 1 LS_NOSERIE FROM F_LOTSERIE WHERE DL_NOIN = DL_No) WHEN 3 THEN (SELECT top 1 LS_NOSERIE FROM F_LOTSERIE WHERE DL_NOOUT = DL_No) END WHEN 5 THEN CASE DL_MvtStock WHEN 0 THEN (SELECT top 1 LS_NOSERIE FROM F_LOTSERIE WHERE DL_NOOUT = DL_No) WHEN 1 THEN (SELECT top 1 LS_NOSERIE FROM F_LOTSERIE WHERE DL_NOIN = DL_No) WHEN 3 THEN (SELECT top 1 LS_NOSERIE FROM F_LOTSERIE WHERE DL_NOOUT = DL_No) END END AS Expr1) AS [N° Série / Lot], CASE FART.AR_SUIVISTOCK WHEN 0 THEN ''Aucun'' WHEN 1 THEN ''Sérialisé'' WHEN 2 THEN ''CMUP'' WHEN 3 THEN ''FIFO'' WHEN 4 THEN ''LIFO'' WHEN 5 THEN ''Par lot'' END AS [Suivi Stock], P_GAMME.G_Intitule AS [Gamme 1], P_GAMME_1.G_Intitule AS [Gamme 2], NULLIF ((SELECT CASE AR_SUIVISTOCK WHEN 1 THEN CASE DL_MvtStock WHEN 1 THEN (SELECT DISTINCT MAX(LS_PEREMPTION) FROM F_LOTSERIE WHERE DL_NOIN = DL_No) WHEN 3 THEN (SELECT DISTINCT MAX(LS_PEREMPTION) FROM F_LOTSERIE WHERE DL_NOOUT = DL_No) END WHEN 5 THEN CASE DL_MvtStock WHEN 1 THEN (SELECT DISTINCT MAX(LS_PEREMPTION) FROM F_LOTSERIE WHERE DL_NOIN = DL_No) WHEN 3 THEN (SELECT DISTINCT MAX(LS_PEREMPTION) FROM F_LOTSERIE WHERE DL_NOOUT = DL_No) END END AS Expr1), ''01/01/1900'') AS [Date Péremption], NULLIF ((SELECT CASE AR_SUIVISTOCK WHEN 1 THEN CASE DL_MvtStock WHEN 1 THEN (SELECT DISTINCT MAX(LS_FABRICATION) FROM F_LOTSERIE WHERE DL_NOIN = DL_No) WHEN 3 THEN (SELECT DISTINCT MAX(LS_FABRICATION) FROM F_LOTSERIE WHERE DL_NOOUT = DL_No) END WHEN 5 THEN CASE DL_MvtStock WHEN 1 THEN (SELECT DISTINCT MAX(LS_FABRICATION) FROM F_LOTSERIE WHERE DL_NOIN = DL_No) WHEN 3 THEN (SELECT DISTINCT MAX(LS_FABRICATION) FROM F_LOTSERIE WHERE DL_NOOUT = DL_No) END END AS Expr1), ''01/01/1900'') AS [Date Fabrication], CASE CASE WHEN (f_docligne.DO_TYPE = 27 AND DL_MVTSTOCK = 1 AND DL_QTE < 0) OR (f_docligne.DO_TYPE = 20 AND LEFT(f_docligne.DO_PIECE, 1) = ''i'') OR DL_MVTSTOCK = 4 THEN 3 ELSE DL_MVTSTOCK END WHEN 3 THEN ''Sortie'' ELSE ''Entrée'' END AS [Sens de mouvement], F_DOCLIGNE.DL_No AS [N° interne], CASE DL_MVTSTOCK WHEN 0 THEN CASE WHEN DL_TYPEPL = 0 AND f_docligne.DO_TYPE = 23 THEN ROUND(DL_CMUP, 2) ELSE 0 END WHEN 1 THEN CASE WHEN f_docligne.DO_TYPE = 27 AND DL_QTE < 0 THEN ROUND(-DL_CMUP * ABS(DL_QTE), 2) WHEN DL_TYPEPL = 0 AND f_docligne.DO_TYPE = 23 THEN ROUND(DL_CMUP * ABS(DL_QTE), 2) ELSE ROUND(DL_CMUP * ABS(DL_QTE), 2) END WHEN 3 THEN CASE WHEN DL_TYPEPL = 0 AND f_docligne.DO_TYPE = 23 THEN ROUND(-DL_CMUP * ABS(DL_QTE), 2) ELSE ROUND(-DL_CMUP * ABS(DL_QTE), 2) END WHEN 4 THEN CASE WHEN f_docligne.DO_DOMAINE = 1 AND (DL_TYPEPL = 2 OR DL_TYPEPL = 3) AND f_docligne.DO_TYPE <> 16 THEN ROUND(DL_CMUP * ABS(DL_QTE), 2) WHEN DL_TYPEPL = 2 AND f_docligne.DO_TYPE = 16 THEN ROUND(DL_CMUP, 2) WHEN DL_TYPEPL = 0 THEN CASE f_docligne.DO_TYPE WHEN 15 THEN ROUND(-DL_CMUP, 2) WHEN 22 THEN ROUND(-DL_CMUP, 2) ELSE ROUND(DL_CMUP, 2) END ELSE ROUND(-DL_CMUP * ABS(DL_QTE), 2) END ELSE ROUND(DL_CMUP * ABS(DL_QTE), 2) END AS [Montant Stock], F_DOCLIGNE.CO_No AS [Code coloboratore], F_COLLABORATEUR.CO_Nom AS [Représentant], F_CATALOGUE_1.CL_Intitule AS [Catalogue 1], F_CATALOGUE_2.CL_Intitule AS [Catalogue 2], F_CATALOGUE_3.CL_Intitule AS [Catalogue 3], F_CATALOGUE_4.CL_Intitule AS [Catalogue 4], CASE F_DOCLIGNE.DO_domaine WHEN 2 THEN F_DEPOT_1.DE_Intitule ELSE F_COMPTET.CT_Intitule END AS [Intitulé tiers], CASE F_DOCLIGNE.DO_domaine WHEN 2 THEN '''' ELSE F_COMPTET.CT_num END AS [Code tiers] ,AR_RefCompose [Article composé] ,F_DOCLIGNE.cbModification [Date modification] FROM F_CATALOGUE AS F_CATALOGUE_1 RIGHT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_3 RIGHT OUTER JOIN F_COLLABORATEUR RIGHT OUTER JOIN F_FAMILLE INNER JOIN F_ARTICLE AS FART INNER JOIN F_DOCLIGNE AS F_DOCLIGNE ON FART.cbAR_Ref = F_DOCLIGNE.cbAR_Ref INNER JOIN F_DEPOT ON F_DOCLIGNE.DE_No = F_DEPOT.DE_No ON F_FAMILLE.FA_CodeFamille = FART.FA_CodeFamille INNER JOIN F_DOCENTETE ON F_DOCLIGNE.DO_Piece = F_DOCENTETE.DO_Piece AND F_DOCLIGNE.DO_Type = F_DOCENTETE.DO_Type ON F_COLLABORATEUR.CO_No = F_DOCLIGNE.cbCO_No LEFT OUTER JOIN F_COMPTET ON F_DOCLIGNE.CT_Num = F_COMPTET.CT_Num LEFT OUTER JOIN F_DEPOT AS F_DEPOT_1 ON F_DOCLIGNE.CT_Num = CAST(F_DEPOT_1.DE_No AS varchar(255)) LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_4 ON FART.CL_No4 = F_CATALOGUE_4.CL_No ON F_CATALOGUE_3.CL_No = FART.CL_No3 ON F_CATALOGUE_1.CL_No = FART.CL_No1 LEFT OUTER JOIN F_CATALOGUE AS F_CATALOGUE_2 ON FART.CL_No2 = F_CATALOGUE_2.CL_No LEFT OUTER JOIN P_GAMME AS P_GAMME_1 ON F_DOCLIGNE.AG_No2 = P_GAMME_1.cbIndice LEFT OUTER JOIN P_GAMME ON F_DOCLIGNE.AG_No1 = P_GAMME.cbIndice WHERE (F_DOCLIGNE.DL_MvtStock = 0 AND F_DOCLIGNE.DL_TypePL = 0 OR F_DOCLIGNE.DL_MvtStock = 0 AND F_DOCLIGNE.DL_TypePL = 2 OR F_DOCLIGNE.DL_MvtStock = 1 AND F_DOCLIGNE.DL_TypePL = 0 OR F_DOCLIGNE.DL_MvtStock = 1 AND F_DOCLIGNE.DL_TypePL = 1 OR F_DOCLIGNE.DL_MvtStock = 3 AND F_DOCLIGNE.DL_TypePL = 0 OR F_DOCLIGNE.DL_MvtStock = 4 AND F_DOCLIGNE.DL_TypePL = 0 OR F_DOCLIGNE.DL_MvtStock = 4 AND F_DOCLIGNE.DL_TypePL = 2 OR F_DOCLIGNE.DL_MvtStock = 1 OR F_DOCLIGNE.DL_MvtStock = 3) AND (F_DOCLIGNE.DL_Qte <> 0) AND (F_DOCLIGNE.DE_No > 0) AND (F_DOCLIGNE.DL_MvtStock > 0) AND (F_DOCLIGNE.DL_MvtStock = 1 OR F_DOCLIGNE.DL_MvtStock = 3 OR FART.AR_SuiviStock = 2 OR F_DOCLIGNE.DO_Type < 15 OR F_DOCLIGNE.DO_Type > 15 AND F_DOCLIGNE.DL_TypePL < 2 OR F_DOCLIGNE.DL_TypePL > 3 AND F_DOCLIGNE.DO_Type < 22 OR F_DOCLIGNE.DO_Type > 22)',
N'Mouvement_stock', N'N° interne', N'DB', 'incremental', N'Date modification', 'normal', 25, 0);

