-- 22. Plan reporting (FULL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Plan reporting',
N'SELECT [CR_Num] Code, CASE WHEN [CR_Type] = 0 THEN ''Détail'' ELSE ''Total'' END [Type de compte], [CR_Intitule] Intitulé FROM [F_COMPTER]',
N'Plan_Reporting', NULL, N'DB', 'full', NULL, 'normal', 27, 0);

-- 23. Plan comptable (FULL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Plan comptable',
N'SELECT CG_Num [Numéro compte], case when CG_Type=0 then ''Détail'' else ''Total'' end [Type de compte], CG_Intitule Intitulé, CG_Classement Classement, case N_Nature when 0 then ''Aucune'' when 1 then ''Client'' when 2 then ''Fournisseur'' when 3 then ''Salarié'' when 4 then ''Banque'' when 5 then ''Caisse'' when 6 then ''Amortissement/Provision'' when 7 then ''Résultat bilan'' when 8 then ''charge'' when 9 then ''Produit'' when 10 then ''Résultat Gestion'' when 11 then ''Immobilisation'' when 12 then ''Capitaux'' when 13 then ''Stock'' when 14 then ''Titre'' end Nature, case CG_Report when 0 then ''Aucun'' when 1 then ''Solde'' when 2 then ''Détail'' end [Type report], F_COMPTEG.CR_Num [Code reporting], case when CG_Sommeil=0 then ''Actif'' else ''En sommeil'' end [Mise en sommeil], F_COMPTEG.cbCreation [Date de création], F_COMPTER.CR_Intitule [Intitulé reporting] FROM F_COMPTEG LEFT OUTER JOIN F_COMPTER ON F_COMPTEG.CR_Num = F_COMPTER.CR_Num',
N'Plan_Comptable', N'Numéro compte', N'DB', 'full', NULL, 'normal', 28, 1);

-- 24. Ecritures Comptables (INCREMENTAL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Les écritures comptables',
N'SELECT F_ECRITUREC.JM_Date + F_ECRITUREC.EC_Jour - 1 AS [Date d''écriture], F_ECRITUREC.CG_Num AS [N° Compte Général], F_COMPTEG_1.CG_Intitule as [Intitulé compte général], F_ECRITUREC.CT_Num AS [Compte Tiers], F_COMPTET_1.CT_Intitule as [Intitulé tiers], F_ECRITUREC.EC_Piece AS [N° Pièce], F_ECRITUREC.EC_RefPiece AS [N° facture], F_ECRITUREC.JO_Num AS [Code Journal], F_ECRITUREC.EC_TresoPiece AS [N° Pièce de tréso], F_ECRITUREC.EC_Intitule AS [Libellé], CASE EC_SENS WHEN 0 THEN EC_MONTANT ELSE cast( 0 as float) END AS [Débit], CASE EC_SENS WHEN 1 THEN EC_MONTANT ELSE cast( 0 as float) END AS [Crédit], CAST('''' AS VARCHAR(64) ) AS Masse,CAST('''' AS VARCHAR(64) ) AS Rubrique,CAST('''' AS VARCHAR(64) ) AS Poste,CAST('''' AS VARCHAR(64) ) AS [Compte principal], CASE F_COMPTEG_1.CG_Report WHEN 0 THEN ''Aucun'' WHEN 1 THEN ''Solde'' WHEN 2 THEN ''Détail'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Report à Nouveau], CASE F_COMPTEG_1.CG_Regroup WHEN 0 THEN ''Non Validée'' WHEN 1 THEN ''Validée'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Regroupement], CASE F_COMPTEG_1.CG_Analytique WHEN 0 THEN ''Non Validée'' WHEN 1 THEN ''Validée'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Saisie Analytique], CASE F_COMPTEG_1.CG_Echeance WHEN 0 THEN ''Non Validée'' WHEN 1 THEN ''Validée'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Saisie Echéance], CASE F_COMPTEG_1.CG_Quantite WHEN 0 THEN ''Non Validée'' WHEN 1 THEN ''Validée'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Saisie Quantité], F_ECRITUREC.cbMarq AS [Clé Comptabilité], CAST(YEAR( F_ECRITUREC.JM_Date) AS varchar) AS Exercice, F_ECRITUREC.EC_No AS [N° interne], F_ECRITUREC.EC_Nolink AS [N° interne de lien], F_ECRITUREC.EC_Date AS [Date de saisier], CASE EC_POINT WHEN 0 THEN ''NON'' WHEN 1 THEN ''OUI'' END AS Pointage, F_ECRITUREC.EC_Pointage AS [Lettre de pointage], CASE EC_LETTRE WHEN 0 THEN ''NON'' WHEN 1 THEN ''OUI'' END AS Lettrage, F_ECRITUREC.EC_Lettrage AS Lettre, CASE YEAR(EC_ECHEANCE) WHEN 1900 THEN NULL ELSE EC_ECHEANCE END AS [Date d''échéance], CASE EC_RTYPE WHEN 0 THEN ''Non Révisée'' WHEN 1 THEN ''Révisée'' ELSE ''ERREUR. Contactez votre revendeur.'' END AS Révision, F_ECRITUREC.EC_Parite AS Parité, F_ECRITUREC.EC_Quantite AS Quantité, F_ECRITUREC.CT_NumCont AS [Contrepartie Tiers], F_ECRITUREC.TA_Code AS [Code Taxe], CASE EC_SENS WHEN 0 THEN ''Débit'' WHEN 1 THEN ''Crédit'' ELSE ''ERREUR. Contactez votre revendeur.'' END AS [Sens], F_ECRITUREC.EC_Rappel AS [Niveau Rappel], CASE EC_SENS WHEN 0 THEN EC_MONTANT WHEN 1 THEN - EC_MONTANT ELSE ''ERREUR. Contactez votre revendeur.'' END AS [Montant], CASE EC_SENS WHEN 0 THEN - EC_DEVISE WHEN 1 THEN + EC_DEVISE ELSE ''ERREUR. Contactez votre revendeur.'' END AS [Montnat en devis], ISNULL(P_REGLEMENT.R_Intitule, ''AUCUN'') AS [Mode de réglement], CASE WHEN EC_ANTYPE BETWEEN 1 AND 4 THEN ''OUI'' ELSE ''NON'' END AS [Type à Nouveau], CASE EC_ANTYPE WHEN 0 THEN ''Ecriture'' WHEN 1 THEN ''Ecriture reprise détail'' WHEN 2 THEN ''Ecriture reprise solde'' WHEN 3 THEN ''Ecriture à nouveau manuel'' WHEN 4 THEN ''Ecriture à nouveau Résultat'' ELSE ''NON'' END AS [Type Ecriture], ISNULL(P_DEVISE.D_Intitule, ''AUCUNE'') AS [Devise], F_ECRITUREC.EC_Reference AS [Référence], (SELECT DISTINCT DR_Num FROM F_DRECOUVREMENTEC WHERE (EC_No = F_ECRITUREC.EC_No)) AS [N° Dossier Recouvrement], CASE F_COMPTET_1.CT_Type WHEN 0 THEN ''Client'' WHEN 1 THEN ''Fournisseur'' WHEN 2 THEN ''Salarié'' WHEN 3 THEN ''Autres'' ELSE ''Aucune'' END AS [Type tiers] , CASE N_Nature WHEN 0 THEN ''Aucune'' WHEN 1 THEN ''Client'' WHEN 2 THEN ''Fournisseur'' WHEN 3 THEN ''Salarié'' WHEN 4 THEN ''Banque'' WHEN 5 THEN ''Caisse'' WHEN 6 THEN ''Amortissement/Provision'' WHEN 7 THEN ''Résultat - Bilan'' WHEN 8 THEN ''Charge'' WHEN 9 THEN ''Produit'' WHEN 10 THEN ''Résultat - Gestion'' WHEN 11 THEN ''Immobilisation'' WHEN 12 THEN ''Capitaux'' WHEN 13 THEN ''Stock'' WHEN 14 THEN ''Titre'' ELSE ''ERREUR. Contacter votre revendeur.'' END AS [Nature Compte], F_JOURNAUX.JO_Intitule as [Libellé Journal], CASE F_JOURNAUX.JO_Type WHEN 0 THEN ''Achats'' WHEN 1 THEN ''Ventes'' WHEN 2 THEN ''Trésorerie'' WHEN 3 THEN ''Général'' WHEN 4 THEN ''Situation'' END AS [Type Code Journal] ,(F_ECRITUREC.JM_Date) as Mois ,year(F_ECRITUREC.JM_Date) as Année ,F_ECRITUREC.cbModification [Date modification] FROM F_ECRITUREC INNER JOIN F_COMPTEG AS F_COMPTEG_1 ON F_ECRITUREC.CG_Num = F_COMPTEG_1.CG_Num INNER JOIN F_JOURNAUX ON F_ECRITUREC.JO_Num = F_JOURNAUX.JO_Num LEFT OUTER JOIN P_DEVISE ON F_ECRITUREC.N_Devise = P_DEVISE.cbIndice LEFT OUTER JOIN P_REGLEMENT ON F_ECRITUREC.N_Reglement = P_REGLEMENT.cbIndice LEFT OUTER JOIN F_COMPTET AS F_COMPTET_1 ON F_ECRITUREC.CT_Num = F_COMPTET_1.CT_Num',
N'Ecritures_Comptables', N'N° interne', N'DB', 'incremental', N'Date modification', 'normal', 29, 1);

-- 25. Ecritures Analytiques (FULL)
INSERT INTO ETL_Tables_Config (table_name, source_query, target_table, join_column, filter_column, sync_type, timestamp_column, priority, sort_order, delete_orphans)
VALUES (N'Ecritures Analytiques',
N'SELECT F_ECRITUREA.cbMarq [N° interne], F_ECRITUREA.EC_No AS [N° interne EG], F_ECRITUREA.N_Analytique, F_ECRITUREA.EA_Ligne AS Ligne, F_ECRITUREA.CA_Num AS [Compte analytique], F_ECRITUREA.EA_Montant AS [Montant analytique], F_ECRITUREA.EA_Quantite AS Quantité, P_ANALYTIQUE.A_Intitule AS Intitulé, P_ANALYSE.A_Intitule [Plan analytique] FROM F_ECRITUREA INNER JOIN F_COMPTEA ON F_ECRITUREA.N_Analytique = F_COMPTEA.N_Analytique AND F_ECRITUREA.CA_Num = F_COMPTEA.CA_Num INNER JOIN P_ANALYTIQUE ON F_COMPTEA.CA_Num = P_ANALYTIQUE.CA_Num INNER JOIN P_ANALYSE ON F_ECRITUREA.N_Analytique = P_ANALYSE.cbIndice',
N'Ecritures_Analytiques', NULL, N'DB', 'full', NULL, 'normal', 30, 0);

